    const mobil = window.matchMedia?.("(pointer: coarse)").matches;
    if (mobil && typeof navigator.share === "function") {
      try {
        await navigator.share({ title: document.title, url });
        return;
      } catch (e) {
        if (e?.name === "AbortError") return;
