        {teilbar && (
          <button type="button" onClick={teilen} className={knopf}>
            {nativ ? (
              <Share2 aria-hidden="true" className="h-4 w-4 text-ink-500" />
            ) : (
              <Link2 aria-hidden="true" className="h-4 w-4 text-ink-500" />
            )}
