"use client";

import { createContext, useContext, useEffect, useRef } from "react";

/* ------------------------------------------------------------------
   Gemeinsamer Zustand eines Rechner-Rahmens:
   – Kurzwerte (aus <MobilKurz>) für die klebende Leiste und den
     Szenario-Vergleich,
   – optional der Eingabezustand (useTeilbarerZustand) für teilbare Links
     und „Szenario wiederherstellen“.
   ------------------------------------------------------------------ */

export const RahmenKontext = createContext(null);

export const useRahmen = () => useContext(RahmenKontext);

const istZahl = (v) => typeof v === "number" && Number.isFinite(v);

/** Wert aus der Adresszeile prüfen – nur bekannte Schlüssel, passende Typen, plausible Größen. */
function lesenAusUrl(standard, { optionen = {}, grenzen = {} }) {
  if (typeof window === "undefined") return {};
  const p = new URLSearchParams(window.location.search);
  const neu = {};
  for (const [k, std] of Object.entries(standard)) {
    if (!p.has(k)) continue;
    const roh = p.get(k);
    if (typeof std === "number") {
      const n = Number(roh);
      if (!istZahl(n)) continue;
      if (grenzen[k]) {
        neu[k] = Math.min(grenzen[k][1], Math.max(grenzen[k][0], n));
      } else {
        // Ohne Grenzen nur plausible Werte (gleiches Vorzeichen, nicht absurd groß)
        const deckel = Math.max(Math.abs(std) * 50, 1000);
        if (Math.abs(n) > deckel || (std > 0 && n < 0) || (std < 0 && n > 0)) continue;
        neu[k] = n;
      }
    } else if (typeof std === "boolean") {
      if (roh === "1" || roh === "0") neu[k] = roh === "1";
    } else if (typeof std === "string") {
      if (optionen[k]?.includes(roh)) neu[k] = roh;
    }
  }
  return neu;
}

/**
 * Macht den Eingabezustand eines Rechners teilbar: Abweichungen vom
 * Standard landen (verzögert) in der Adresszeile, ein geteilter Link stellt
 * sie beim Öffnen wieder her. Registriert den Zustand außerdem beim
 * umgebenden <RechnerRahmen> (Szenario-Vergleich: „A wiederherstellen“).
 *
 *   const [e, setE] = useState(STANDARD);
 *   useTeilbarerZustand(e, (neu) => setE((a) => ({ ...a, ...neu })), {
 *     optionen: { profil: LASTPROFILE.map((p) => p.id) },
 *     grenzen: { laufzeit: [3, 20] },
 *     pruefen: (z) => rechnePpa(z),
 *   });
 *
 * optionen  erlaubte Texte je Schlüssel (andere Texte aus der URL werden ignoriert)
 * grenzen   [min, max] je Zahl (Werte werden begrenzt)
 * pruefen   optional: (zusammengeführt, nurAusUrl) => …; wirft die Funktion, bleibt der Standard
 */
export function useTeilbarerZustand(werte, uebernehmen, einstellungen = {}) {
  const rahmen = useRahmen();
  const standard = useRef(werte);
  const aktuell = useRef(werte);
  const uebernehmenRef = useRef(uebernehmen);
  const einstellungenRef = useRef(einstellungen);
  const bereit = useRef(false);
  aktuell.current = werte;
  uebernehmenRef.current = uebernehmen;
  einstellungenRef.current = einstellungen;

  // Beim Öffnen: Werte aus einem geteilten Link übernehmen
  useEffect(() => {
    const neu = lesenAusUrl(standard.current, einstellungenRef.current);
    if (Object.keys(neu).length) {
      let ok = true;
      if (einstellungenRef.current.pruefen) {
        try {
          einstellungenRef.current.pruefen({ ...standard.current, ...neu }, neu);
        } catch {
          ok = false;
        }
      }
      if (ok) uebernehmenRef.current(neu);
    }
    bereit.current = true;
  }, []);

  // Beim Rahmen anmelden (Szenario wiederherstellen)
  const zustandRef = rahmen?.zustand;
  useEffect(() => {
    if (!zustandRef) return undefined;
    zustandRef.current = {
      lesen: () => ({ ...aktuell.current }),
      setzen: (z) => uebernehmenRef.current(z),
    };
    return () => {
      zustandRef.current = null;
    };
  }, [zustandRef]);

  // Änderungen verzögert in die Adresszeile schreiben (ohne Verlaufseintrag)
  const schluessel = JSON.stringify(werte);
  useEffect(() => {
    if (!bereit.current || typeof window === "undefined") return undefined;
    const t = setTimeout(() => {
      const p = new URLSearchParams(window.location.search);
      for (const [k, std] of Object.entries(standard.current)) {
        const v = aktuell.current[k];
        if (typeof std === "object" || v === undefined) continue;
        if (v === std) p.delete(k);
        else if (typeof v === "boolean") p.set(k, v ? "1" : "0");
        else if (istZahl(v)) p.set(k, String(Math.round(v * 1e6) / 1e6));
        else if (typeof v === "string") p.set(k, v);
      }
      const q = p.toString();
      const url = `${window.location.pathname}${q ? `?${q}` : ""}${window.location.hash}`;
      if (url !== `${window.location.pathname}${window.location.search}${window.location.hash}`) {
        try {
          window.history.replaceState(null, "", url);
        } catch {
          /* z. B. in eingebetteten Ansichten nicht erlaubt */
        }
      }
    }, 400);
    return () => clearTimeout(t);
  }, [schluessel]);
}

/** Kurzwerte (Label/Wert-Paare aus <MobilKurz>) beim Rahmen melden. */
export function useKurzwerteMelden(werte) {
  const rahmen = useRahmen();
  const schluessel = werte.map(([k, v]) => `${k}\u0000${typeof v === "string" || typeof v === "number" ? v : ""}`).join("\u0001");
  const setKurz = rahmen?.setKurz;
  useEffect(() => {
    if (!setKurz) return;
    // Nur bei echter Änderung setzen (sonst Endlosschleife über den Kontext)
    setKurz((alt) => {
      const neu = werte.map(([k, v]) => [String(k), typeof v === "string" || typeof v === "number" ? String(v) : ""]);
      const gleich = alt && alt.length === neu.length && alt.every(([k, v], i) => k === neu[i][0] && v === neu[i][1]);
      return gleich ? alt : neu;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [schluessel, setKurz]);
}

"use client";

import { useEffect, useRef } from "react";
import Link from "@/components/Land/Link";
import { ArrowUpRight, Clock3 } from "lucide-react";
import Button from "@/components/ui/Button";
import { cn } from "@/components/ui/cn";
import { msSeitEingabe } from "./bausteine";
import BerichtAnfordern from "@/components/Bericht/BerichtAnfordern";

/* ------------------------------------------------------------------
   Ergebnis → passende Anfrage. Steht am Ende jedes Rechner-Ergebnisses:
   die gerade berechnete Hauptzahl, ein Versprechen ohne Druck und EIN
   klarer nächster Schritt. Beim Klick wird die Anfrage vorbelegt
   (sessionStorage, gleiches Format wie formular/Entwurf) – Nachricht mit
   den Eingaben und dem Teilen-Link. Ohne JS bleibt es ein normaler Link.
   ------------------------------------------------------------------ */

const PRAEFIX = "ov-entwurf:";
const MARKE = "Aus dem "; // eigene Vorbelegungen erkennen: überschreiben ja, Nutzertext nie

/** Nachricht der Anfrage `anfrage-<typ>` vorbelegen (nur leer oder eigene frühere Vorbelegung). */
export function anfrageVorbelegen(typ, nachricht) {
  if (!typ || !nachricht) return;
  try {
    const schluessel = `${PRAEFIX}anfrage-${typ}`;
    const alt = JSON.parse(window.sessionStorage.getItem(schluessel) || "null")?.werte || {};
    if (alt.nachricht && !String(alt.nachricht).startsWith(MARKE)) return;
    const text = `${nachricht}\n\nMeine Eingaben: ${window.location.href}`.slice(0, 4800);
    window.sessionStorage.setItem(schluessel, JSON.stringify({ werte: { ...alt, nachricht: text }, zeit: Date.now() }));
  } catch {
    /* Speicher gesperrt (privater Modus) – der Link funktioniert trotzdem */
  }
}

const bewegungReduziert = () => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

/**
 * typ        Anfrage-Typ (/kontakt?anliegen=<typ> bzw. Formular am Ziel), bestimmt den Entwurfsschlüssel
 * href       Ziel der Anfrage (crawlbarer Link)
 * kennzahl   die gerade berechnete Hauptzahl (ReactNode, z. B. <Zahl …/>)
 * satz       Text nach der Zahl, z. B. „Projekt-IRR – mit Ihren Projektdaten nachrechnen lassen“
 * nachricht  Text für die vorbelegte Anfrage (beginnt mit „Aus dem …“)
 * signal     Wert, dessen Änderung nach einer Eingabe die Karte kurz aufleuchten lässt
 * sekundaer  [{ href, label }] – leise Textlinks, kein zweiter lauter Knopf
 * bericht    optional { rechner, land, eingaben } – ruhiger Zusatz „Ergebnis als Bericht“ (Welle 2, Paket B4,
 *            src/components/Bericht/BerichtAnfordern.js); das Ergebnis bleibt immer frei sichtbar
 */
export default function ErgebnisAnfrage({
  typ,
  href,
  eyebrow = "Mit diesem Ergebnis weiter",
  kennzahl,
  satz,
  nachricht,
  label = "Mit diesem Ergebnis anfragen",
  versprechen = "Wir melden uns persönlich – kostenlos und unverbindlich.",
  signal,
  sekundaer = [],
  hinweis,
  bericht,
  className,
}) {
  const leuchten = useRef(null);
  const zuletzt = useRef(-1e9);
  const erst = useRef(true);

  // Feedback: Ergebnis hat sich durch eine Eingabe verändert → Karte leuchtet einmal leise auf
  // (nur opacity, höchstens alle 6 s, nur wenn die Karte im Bild ist, nie beim Laden).
  useEffect(() => {
    if (erst.current) {
      erst.current = false;
      return undefined;
    }
    if (msSeitEingabe() > 800 || bewegungReduziert()) return undefined;
    const t = setTimeout(() => {
      const el = leuchten.current;
      if (!el || typeof el.animate !== "function") return;
      const jetzt = performance.now();
      if (jetzt - zuletzt.current < 6000) return;
      const box = el.getBoundingClientRect();
      if (box.bottom < 60 || box.top > window.innerHeight - 60) return;
      zuletzt.current = jetzt;
      el.animate([{ opacity: 0 }, { opacity: 1, offset: 0.35 }, { opacity: 0 }], { duration: 1200, easing: "cubic-bezier(.2,.8,.2,1)" });
    }, 650);
    return () => clearTimeout(t);
  }, [signal]);

  return (
    <div className={cn("mt-7 border-t border-ink-100 pt-6", className)}>
      <div data-ergebnis-anfrage="" className="relative isolate overflow-hidden rounded-3xl bg-ov-50 p-5 ring-1 ring-ov-200 print:hidden md:p-6">
        {/* Aufleuchten (aria-hidden, lässt Klicks durch) */}
        <span
          ref={leuchten}
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 -z-10 rounded-3xl opacity-0 ring-2 ring-inset ring-ov-400"
          style={{ background: "radial-gradient(120% 140% at 0% 0%, rgba(174,208,131,0.45), transparent 60%)" }}
        />
        <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          <div className="min-w-0">
            <p className="text-[13px] font-semibold text-ov-800">{eyebrow}</p>
            <p className="mt-1 font-display text-[19px] font-bold leading-snug text-ink-900">
              {kennzahl != null && (
                <>
                  ≈ <span className="ov-num whitespace-nowrap">{kennzahl}</span>{" "}
                </>
              )}
              {satz}
            </p>
            <p className="mt-1.5 flex items-start gap-1.5 text-[13px] leading-snug text-ink-600">
              <Clock3 aria-hidden="true" className="mt-0.5 h-3.5 w-3.5 shrink-0 text-ov-600" />
              {versprechen}
            </p>
          </div>
          <Button href={href} size="lg" pfeil className="w-full shrink-0 sm:w-auto" data-ov-cta onClick={() => anfrageVorbelegen(typ, nachricht)}>
            {label}
          </Button>
        </div>
        {sekundaer.length > 0 && (
          <ul className="mt-4 flex flex-wrap gap-x-5 gap-y-1 border-t border-ov-200/70 pt-3">
            {sekundaer.map((s) => (
              <li key={s.href}>
                <Link
                  href={s.href}
                  className="group inline-flex min-h-10 items-center gap-1 rounded-lg text-[14px] font-semibold text-ov-800 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500"
                >
                  {s.label}
                  <ArrowUpRight aria-hidden="true" className="ov-pfeil h-4 w-4" />
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
      {hinweis && <p className="mt-4 text-[13px] leading-relaxed text-ink-500">{hinweis}</p>}
      {bericht?.rechner && <BerichtAnfordern rechner={bericht.rechner} land={bericht.land} eingaben={bericht.eingaben} />}
    </div>
  );
}
