    { weg: "C", titel: "Verpachten", invest: "keine Investition", energie: [`Agri-Pacht ${fmt(PACHT.agriProHa.mittel)} €/ha, +${fmt(PACHT.indexierung * 100, 1)} % p. a.`], energieLand: ["Agri-Pacht, indexiert"] },
