          </Hauptzahl>
          <Belege>
            <Kennzahl ton="akzent" icon={Gauge} label="Wert je kWp" zusatz={`Spanne ${fmt(r.spanneProKwp.min)}–${fmt(r.spanneProKwp.max)} €`}>
