    netz: "Grid",
    entfernung: "Distance to the connection point",
    entfernungHinweis: "Route length to the MV line or substation – usually longer than as the crow flies.",
    ebene: "Voltage level",
    kapazitaet: "Available grid capacity",
    cluster: "Clustering with a neighbouring project",
    clusterText: "shared cable route or shared substation",
    sr: (a, b, c, d) => `Grid connection roughly ${a} to ${b}, time frame ${c} to ${d} months.`,
    ihr: "Your grid connection",
    hauptLabel: "Cost of the grid connection (mid-point)",
    spanne: (a, b) => `Range ${a} – ${b}`,
    anlagenkosten: (x) => `${x}% of the plant costs`,
    zeitrahmen: "Time frame",
    abBegehren: "from a complete request",
    anschlussK: "Connection",
    systeme: (n) => `${n} × 20 kV system`,
    erwartet: (mw, l) => `For ${mw} MW, “${l}” would typically be expected.`,
    ihrAnteil: "(your share)",
    fuss: "Rough guidance without guarantee. Only the grid operator’s grid compatibility check and cost estimate are binding.",
    pruefen: "Have your land checked",
    ueberTitel: "Overbuilding: is less connection capacity worthwhile?",
    voll: "You are calculating with full connection capacity. Set the “Connection capacity” slider to 70–80%: grid costs often fall while only a few percent of yield are lost.",
    gespart: "Grid costs saved",
    gg100: "vs. 100% connection",
    verlust: "Yield loss",
    verlustZusatz: (a, b) => `${a} MWh · ${b} per year`,
    barwert: "Present value of loss, 20 yrs",
    kleiner: "smaller than the savings",
    groesser: "larger than the savings",
    auffang: (x) => `The storage absorbs a calculated ${x}% of the curtailment.`,
    ueberFuss: "Capacity often becomes available sooner if you offer limited feed-in – for example via a flexible grid connection agreement under § 8a EEG. Yield loss valued at the EEG award, discounted at 5%.",
    risiken: "Risks",
    tipps: "Tips",
    ziel: { msLeitung: "MV line", uwMs: "Substation", hs: "110 kV grid" },
    schemaAria: (km, z) => `Sketch: solar park, ${km} km cable route, connection to ${z}`,
    park: (x) => `Park ${x} MWp`,
  },
};
'''),
(r'''  const seitenLand = useSeitenLand();
  const [e, setE]''', r'''  const seitenLand = useSeitenLand();
  const t = useTexte(TEXTE);
  const f = useFormate();
  const { fmt, fmtEur } = f;
  const geld = geldMit(f);
  const en = f.sprache === "en";
  const EBENE_LABEL = t.ebeneLabel;
  const [e, setE]'''),
(r'''  const u = r.ueberbauung;''', r'''  const u = r.ueberbauung;
  const rt = en ? risikenTippsEn(r.eingabe, r, f) : { risiken: r.risiken, tipps: r.tipps };'''),
(r'''<Auswahl legende="Land" wert={e.land} onChange={set("land")} optionen={LAENDER} />''', r'''<Auswahl legende={t.land} wert={e.land} onChange={set("land")} optionen={opt(LAENDER, t.laender)} />'''),
(r'''              ["Kosten", geld(r.summe)],
              ["je kWp", `${fmt(r.proKwp)} €`],
              ["Zeit", `${r.monate[0]}–${r.monate[1]} Mon.`],''', r'''              [t.kosten, geld(r.summe)],
              [t.jeKwp, fmtEur(r.proKwp)],
              [t.zeit, t.monate(r.monate[0], r.monate[1])],'''),
(r'''            <Gruppe titel="Anlage">
              {regionWahl}
              <Regler label="Anlagengröße" wert''', r'''            <Gruppe titel={t.anlage}>
              {regionWahl}
              <Regler label={t.groesse} wert'''),
(r'''                label="Anschlussleistung (Überbauung)"''', r'''                label={t.anschluss}'''),
(r'''                format={(v) => `${fmt(v)} % · ${fmt((e.mwp * v) / 100, 1)} MW`}
                minLabel="50 %"
                maxLabel="100 %"
                onChange={(v) => set("anschlussQuote")(v / 100)}
                hinweis="Einspeiseleistung im Verhältnis zur Modulleistung – weniger Leistung spart Netzkosten, kostet aber etwas Ertrag."''', r'''                format={(v) => t.anschlussFormat(f, v, fmt((e.mwp * v) / 100, 1))}
                minLabel={f.pct(50)}
                maxLabel={f.pct(100)}
                onChange={(v) => set("anschlussQuote")(v / 100)}
                hinweis={t.anschlussHinweis}'''),
(r'''<Schalter icon={BatteryCharging} label="Speicher am selben Anschluss" beschreibung="Co-Location, fängt Spitzen auf"''', r'''<Schalter icon={BatteryCharging} label={t.speicher} beschreibung={t.speicherText}'''),
(r'''<Regler label="Speicherleistung" wert''', r'''<Regler label={t.speicherLeistung} wert'''),
(r'''<Schalter icon={Cable} label="Speicher lädt auch aus dem Netz" beschreibung="dann fällt ein Baukostenzuschuss an"''', r'''<Schalter icon={Cable} label={t.netzbezug} beschreibung={t.netzbezugText}'''),
(r'''            <Gruppe titel="Netz">
              <Regler label="Entfernung zum Anschlusspunkt" wert={e.km} min={0.2} max={20} step={0.1} stellen={1} format={(v) => `${fmt(v, 1)} km`} onChange={set("km")} hinweis="Trassenlänge bis zur MS-Leitung oder zum Umspannwerk – meist länger als Luftlinie." />
              <Auswahl legende="Spannungsebene" wert={e.ebene} onChange={set("ebene")} optionen={EBENEN} spalten={2} klein />
              <Auswahl legende="Freie Netzkapazität" wert={e.kapazitaet} onChange={set("kapazitaet")} optionen={KAPAZITAETEN} klein />
              <Schalter icon={Users} label="Clusterung mit Nachbarprojekt" beschreibung="gemeinsame Trasse bzw. gemeinsames Umspannwerk"''', r'''            <Gruppe titel={t.netz}>
              <Regler label={t.entfernung} wert={e.km} min={0.2} max={20} step={0.1} stellen={1} format={(v) => `${fmt(v, 1)} km`} onChange={set("km")} hinweis={t.entfernungHinweis} />
              <Auswahl legende={t.ebene} wert={e.ebene} onChange={set("ebene")} optionen={opt(EBENEN, t.ebenen)} spalten={2} klein />
              <Auswahl legende={t.kapazitaet} wert={e.kapazitaet} onChange={set("kapazitaet")} optionen={opt(KAPAZITAETEN, t.kapazitaeten)} klein />
              <Schalter icon={Users} label={t.cluster} beschreibung={t.clusterText}'''),
(r'''<p className="sr-only" aria-live="polite">{`Netzanschluss grob ${geld(r.spanne.min)} bis ${geld(r.spanne.max)}, Zeitrahmen ${r.monate[0]} bis ${r.monate[1]} Monate.`}</p>
          <ErgebnisKopf titel="Ihr Netzanschluss" plakette={EBENE_LABEL[r.ebene]} />''', r'''<p className="sr-only" aria-live="polite">{t.sr(geld(r.spanne.min), geld(r.spanne.max), r.monate[0], r.monate[1])}</p>
          <ErgebnisKopf titel={t.ihr} plakette={EBENE_LABEL[r.ebene]} />'''),
(r'''            label="Kosten des Netzanschlusses (Mitte)"
            zusatz={`Spanne ${geld(r.spanne.min)} – ${geld(r.spanne.max)}`}''', r'''            label={t.hauptLabel}
            zusatz={t.spanne(geld(r.spanne.min), geld(r.spanne.max))}'''),
(r'''            {AMPEL_TEXT[r.ampel]}''', r'''            {t.ampelText[r.ampel]}'''),
(r'''<Kennzahl ton="akzent" icon={Percent} label="je kWp" zusatz={`${fmt(r.anteil * 100)} % der Anlagenkosten`}>
              <Zahl wert={r.proKwp} suffix=" €" delta="hell" />
            </Kennzahl>
            <Kennzahl icon={CalendarClock} label="Zeitrahmen" zusatz="ab vollständigem Begehren">
              {r.monate[0]}–{r.monate[1]} Mon.
            </Kennzahl>
            <Kennzahl icon={Network} label="Anschluss" zusatz={`${r.kabelSysteme} × 20-kV-System`}>''', r'''<Kennzahl ton="akzent" icon={Percent} label={t.jeKwp} zusatz={t.anlagenkosten(fmt(r.anteil * 100))}>
              <Zahl wert={r.proKwp} format={(v) => fmtEur(v)} delta="hell" />
            </Kennzahl>
            <Kennzahl icon={CalendarClock} label={t.zeitrahmen} zusatz={t.abBegehren}>
              {t.monate(r.monate[0], r.monate[1])}
            </Kennzahl>
            <Kennzahl icon={Network} label={t.anschlussK} zusatz={t.systeme(r.kabelSysteme)}>'''),
(r'''<p className="mt-3 text-[13px] text-ink-500">Für {fmt(r.anschlussMw, 1)} MW wäre typischerweise „{EBENE_LABEL[r.vorschlag]}“ zu erwarten.</p>''', r'''<p className="mt-3 text-[13px] text-ink-500">{t.erwartet(fmt(r.anschlussMw, 1), EBENE_LABEL[r.vorschlag])}</p>'''),
(r'''                    {p.label}
                    {p.geteilt && <span className="ml-1.5 text-[12px] text-ov-700">(Ihr Anteil)</span>}''', r'''                    {t.posten(p, r)}
                    {p.geteilt && <span className="ml-1.5 text-[12px] text-ov-700">{t.ihrAnteil}</span>}'''),
(r'''<p className="max-w-md text-[13px] leading-relaxed text-ink-500">Grobe Orientierung ohne Gewähr. Verbindlich sind nur Netzverträglichkeitsprüfung und Kostenvoranschlag des Netzbetreibers.</p>''', r'''<p className="max-w-md text-[13px] leading-relaxed text-ink-500">{t.fuss}</p>'''),
(r'''              Fläche prüfen lassen
            </Button>''', r'''              {t.pruefen}
            </Button>'''),
(r'''tracking-tight text-ink-900">Überbauung: lohnt weniger Anschlussleistung?</h3>''', r'''tracking-tight text-ink-900">{t.ueberTitel}</h3>'''),
(r'''                Sie rechnen mit voller Anschlussleistung. Stellen Sie den Regler „Anschlussleistung“ auf 70–80 %: Oft sinken die Netzkosten, während nur wenige Prozent Ertrag verloren gehen.''', r'''                {t.voll}'''),
(r'''<Kennzahl icon={Coins} label="Netzkosten gespart" zusatz="ggü. 100 % Anschluss">''', r'''<Kennzahl icon={Coins} label={t.gespart} zusatz={t.gg100}>'''),
(r'''<Kennzahl icon={AlertTriangle} label="Ertragsverlust" zusatz={`${fmt(u.verlustKwh / 1000)} MWh · ${fmtEur(u.verlustEurJahr)} je Jahr`}>
                  {fmt(u.verlust * 100, 1)} %''', r'''<Kennzahl icon={AlertTriangle} label={t.verlust} zusatz={t.verlustZusatz(fmt(u.verlustKwh / 1000), fmtEur(u.verlustEurJahr))}>
                  {f.fmtPct(u.verlust, 1)}'''),
(r'''label="Barwert Verlust 20 J." zusatz={u.lohnt ? "kleiner als die Ersparnis" : "größer als die Ersparnis"}>''', r'''label={t.barwert} zusatz={u.lohnt ? t.kleiner : t.groesser}>'''),
(r'''<p className="mt-3 text-[13px] text-ink-500">Der Speicher fängt rechnerisch rund {fmt(u.speicherAuffang * 100)} % der Abregelung auf.</p>''', r'''<p className="mt-3 text-[13px] text-ink-500">{t.auffang(fmt(u.speicherAuffang * 100))}</p>'''),
(r'''              Kapazität frei wird oft schneller, wenn Sie eine begrenzte Einspeisung anbieten – etwa über eine flexible Netzanschlussvereinbarung nach § 8a EEG. Ertragsverlust bewertet mit dem EEG-Zuschlag, abgezinst mit 5 %.''', r'''              {t.ueberFuss}'''),
(r'''<AlertTriangle aria-hidden="true" className="h-5 w-5 text-warn-600" /> Risiken''', r'''<AlertTriangle aria-hidden="true" className="h-5 w-5 text-warn-600" /> {t.risiken}'''),
(r'''                {r.risiken.map((t) => (
                  <li key={t} className="flex gap-3 text-[14px] leading-relaxed text-ink-700">
                    <span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-sun-500" aria-hidden="true" />
                    {t}''', r'''                {rt.risiken.map((x) => (
                  <li key={x} className="flex gap-3 text-[14px] leading-relaxed text-ink-700">
                    <span className="mt-2 h-1.5 w-1.5 shrink-0 rounded-full bg-sun-500" aria-hidden="true" />
                    {x}'''),
(r'''<Lightbulb aria-hidden="true" className="h-5 w-5 text-sun-400" /> Tipps''', r'''<Lightbulb aria-hidden="true" className="h-5 w-5 text-sun-400" /> {t.tipps}'''),
(r'''                {r.tipps.map((t, i) => (
                  <li key={t} className="flex gap-3 text-[14px] leading-relaxed text-white/85">
                    <span className="ov-num flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-white/10 text-[12px] font-bold text-ov-300">{i + 1}</span>
                    <span className="min-w-0">{t}</span>''', r'''                {rt.tipps.map((x, i) => (
                  <li key={x} className="flex gap-3 text-[14px] leading-relaxed text-white/85">
                    <span className="ov-num flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-white/10 text-[12px] font-bold text-ov-300">{i + 1}</span>
                    <span className="min-w-0">{x}</span>'''),
(r'''function Schema({ r, km }) {
  const ziel = r.ebene === "msLeitung" ? "MS-Leitung" : r.ebene === "uwMs" ? "Umspannwerk" : "110-kV-Netz";''', r'''function Schema({ r, km }) {
  const t = useTexte(TEXTE);
  const { fmt } = useFormate();
  const ziel = t.ziel[r.ebene];'''),
(r'''aria-label={`Skizze: Solarpark, ${fmt(km, 1)} km Kabeltrasse, Anschluss an ${ziel}`}''', r'''aria-label={t.schemaAria(fmt(km, 1), ziel)}'''),
(r'''            Park {fmt(r.eingabe.mwp)} MWp''', r'''            {t.park(fmt(r.eingabe.mwp))}'''),
]

input.content:
// src/app/rechner/netzanschluss/page.js – Netzanschluss-Check für Solarparks
//
// Sprachmodell: deutsche Texte in DE, englische in EN (gleiche Struktur; Regeln:
// src/lib/sprache/woerterbuch.js). Zahlen im Format der Sprache (src/lib/sprache/zahlformat.js).

import Link from "@/components/Land/Link";
import RechnerSeite, { rechnerMetadata, rechnerMetadataEn } from "@/components/Rechner/RechnerSeite";
import NetzanschlussRechner from "@/components/Rechner/NetzanschlussRechner";
import { FREIFLAECHE, SPEICHER } from "@/lib/invest/markt";
import { CLUSTER_ANTEIL, SPANNE } from "@/lib/rechner/netzanschluss";
import { fmt } from "@/lib/rechner/annahmen";
import { pfad as seitenPfad } from "@/lib/land";
import { seitenLand, seitenMetadata, spracheDerAnfrage } from "@/lib/land/seite";
import { faqFuerLand, NurDEBlock } from "@/components/Land/Laenderteile";
import { uebersetze } from "@/lib/sprache/woerterbuch";
import { formate } from "@/lib/sprache/zahlformat";

const PFAD = seitenPfad("/rechner/netzanschluss");
const N = FREIFLAECHE.netz;
const e = formate("en");

const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Netzanschluss-Check Solarpark: Kosten & Zeit | ÖkoInvest",
  description:
    "Netzanschluss für Solarpark prüfen: grobe Kosten für Kabeltrasse, Übergabestation und Umspannwerk, Zeitrahmen, Risiken und Tipps – mit Überbauung und Speicher.",
  keywords: ["Netzanschluss Solarpark Kosten", "Netzanschlussbegehren § 8 EEG", "Umspannwerk Solarpark", "Überbauung Netzanschluss", "Kabeltrasse Mittelspannung Kosten", "Netzverknüpfungspunkt"],
});

const metadataEn = rechnerMetadataEn({
  title: "Solar park grid connection check: costs & time | ÖkoInvest",
  description:
    "Check the grid connection for a solar park: rough costs for cable route, transfer station and substation, time frame, risks and tips – with overbuilding and storage.",
  keywords: ["solar park grid connection costs", "grid connection request § 8 EEG", "solar park substation", "overbuilding grid connection", "medium-voltage cable route costs", "grid connection point"],
});

const FAQ = [
  {
    q: "Was kostet der Netzanschluss eines Solarparks?",
    a: `Das hängt vor allem von Entfernung und Spannungsebene ab. Als grobe Orientierung rechnen wir mit rund ${fmt(FREIFLAECHE.kabelProMeter)} € je Meter Mittelspannungstrasse, ${fmt(FREIFLAECHE.netzanschlussFixProMwp)} € je MWp für Übergabe- und Trafostationen und – bei großen Parks – mit einem eigenen Umspannwerk 110/20 kV in Millionenhöhe. Wenige Kilometer zur Mittelspannung sind meist gut tragbar; lange 110-kV-Trassen können die Wirtschaftlichkeit kippen.`,
    nurDE: "Kostenwerte",
  },
  {
    q: "Wer trägt welche Kosten?",
    a: "In Deutschland trägt der Anlagenbetreiber die Kosten für den Anschluss bis zum Netzverknüpfungspunkt (§ 16 EEG), der Netzbetreiber die Kosten für den Ausbau seines Netzes (§ 17 EEG). Für reine Einspeiser fällt in der Regel kein Baukostenzuschuss an – wohl aber für Netzbezug, etwa wenn ein Speicher aus dem Netz lädt.",
    nurDE: "Regeln zu Anschlusskosten",
  },
  {
    q: "Wie schnell muss der Netzbetreiber antworten?",
    a: `Nach § 8 Abs. 5 EEG muss er nach Eingang des Netzanschlussbegehrens unverzüglich einen genauen Zeitplan für die Bearbeitung übermitteln und spätestens nach ${N.pruefWochen} Wochen das Ergebnis der Netzverträglichkeitsprüfung samt Kostenvoranschlag vorlegen (§ 8 Abs. 6 EEG) – vorausgesetzt, das Begehren ist vollständig. Der Bau selbst dauert länger: je nach Ebene und Kapazität von rund einem bis zu mehreren Jahren.`,
    nurDE: "Fristen",
  },
  {
    q: "Was bedeutet Überbauung?",
    a: "Bei der Überbauung ist die Modulleistung größer als die Einspeiseleistung am Netzanschluss. Weil ein Solarpark seine volle Leistung nur an wenigen Stunden im Jahr erreicht, geht bei 70–80 % Anschlussleistung oft nur ein kleiner Teil des Ertrags verloren – mit einem Speicher noch weniger. Über eine flexible Netzanschlussvereinbarung nach § 8a EEG lässt sich die maximale Einspeisung vertraglich begrenzen.",
    nurDE: "Regeln",
  },
  {
    q: "Lohnt sich die Clusterung mit Nachbarprojekten?",
    a: `Oft ja: Eine gemeinsame Trasse oder ein gemeinsames Umspannwerk teilt die größten Kostenblöcke. Im Rechner nehmen wir an, dass Sie etwa ${fmt((1 - CLUSTER_ANTEIL) * 100)} % dieser Kosten tragen. Wichtig sind klare Verträge zu Kostenaufteilung, Bauabfolge und Haftung, falls ein Partner später baut.`,
    nurDE: "Kostenwerte",
  },
  {
    q: "Wie ist es in Österreich und der Schweiz?",
    a: "In Österreich erfolgt der Netzzugang beim Verteilnetzbetreiber; es fallen Netzzutrittsentgelte und – für Bezug – Netzbereitstellungsentgelte an, Kapazitäten werden je Netzbereich veröffentlicht. In der Schweiz gelten die Anschlussbedingungen des Verteilnetzbetreibers; notwendige Netzverstärkungen werden in der Regel über die Netzkosten getragen. Die Kostenbausteine im Rechner sind auf Deutschland kalibriert.",
  },
];

const FAQ_EN = [
  {
    q: "What does a solar park’s grid connection cost?",
    a: `That depends mainly on distance and voltage level. As a rough guide, we calculate with around ${e.eur(FREIFLAECHE.kabelProMeter)} per metre of medium-voltage route, ${e.eur(FREIFLAECHE.netzanschlussFixProMwp)} per MWp for transfer and transformer stations and – for large parks – a dedicated 110/20 kV substation costing millions. A few kilometres to the medium-voltage grid are usually quite affordable; long 110 kV routes can tip the economics.`,
    nurDE: "Cost figures",
  },
  {
    q: "Who bears which costs?",
    a: "In Germany, the plant operator bears the costs of the connection up to the grid connection point (§ 16 EEG), and the grid operator bears the costs of expanding its grid (§ 17 EEG). Pure feed-in plants usually pay no construction cost contribution – but grid consumption does, for example when a storage system charges from the grid.",
    nurDE: "Rules on connection costs",
  },
  {
    q: "How quickly must the grid operator respond?",
    a: `Under § 8(5) EEG, after receiving the grid connection request it must promptly send a precise schedule for processing it, and must present the result of the grid compatibility check, including a cost estimate, within ${N.pruefWochen} weeks at the latest (§ 8(6) EEG) – provided the request is complete. Construction itself takes longer: depending on voltage level and capacity, from around one to several years.`,
    nurDE: "Deadlines",
  },
  {
    q: "What does overbuilding mean?",
    a: "With overbuilding, the module capacity is greater than the feed-in capacity at the grid connection. Because a solar park only reaches its full output in a few hours a year, often only a small part of the yield is lost at 70–80% connection capacity – even less with storage. A flexible grid connection agreement under § 8a EEG can contractually limit the maximum feed-in.",
    nurDE: "Rules",
  },
  {
    q: "Is clustering with neighbouring projects worthwhile?",
    a: `Often yes: a shared cable route or a shared substation splits the largest cost blocks. In the calculator, we assume that you bear about ${e.pct((1 - CLUSTER_ANTEIL) * 100)} of these costs. Clear contracts on cost sharing, construction sequence and liability are important in case a partner builds later.`,
    nurDE: "Cost figures",
  },
  {
    q: "How does it work in Austria and Switzerland?",
    a: "In Austria, grid access is granted by the distribution system operator; grid access fees and – for consumption – grid provision fees apply, and capacities are published per grid area. In Switzerland, the connection conditions of the distribution system operator apply; necessary grid reinforcements are usually covered by grid costs. The cost components in the calculator are calibrated for Germany.",
  },
];

const DE = {
  breadcrumb: "Netzanschluss-Check",
  eyebrow: "Für Eigentümer, Projektierer und Investoren",
  title: (
    <>
      Der Netzanschluss entscheidet – <span className="ov-text-gradient-light">prüfen Sie ihn zuerst.</span>
    </>
  ),
  lead: "Größe, Entfernung, Spannungsebene und Netzkapazität eingeben: Sie erhalten grobe Kosten für Trasse, Stationen und Umspannwerk, einen Zeitrahmen, die wichtigsten Risiken und konkrete Tipps – inklusive Überbauung und Speicher.",
  chips: ["Kosten mit Spanne", "Zeitrahmen", "Überbauung & Speicher", "§ 8 EEG-Tipps"],
  app: {
    name: "Netzanschluss-Check Solarpark",
    description: "Grobe Kosten- und Zeitschätzung für den Netzanschluss eines Solarparks nach Größe, Entfernung, Spannungsebene und Netzkapazität – mit Überbauung, Speicher, Clusterung, Risiken und Tipps.",
    featureList: ["Kostenbausteine Kabel, Stationen, Umspannwerk", "Automatische Wahl der Spannungsebene", "Überbauung mit Abregelungsverlust", "Speicher und Baukostenzuschuss", "Zeitrahmen und Risiken", "Tipps zu § 8 und § 8a EEG"],
  },
  annahmen: [
    ["MS-Kabeltrasse", `${fmt(FREIFLAECHE.kabelProMeter)} €/m`],
    ["Übergabe- & Trafostationen", `${fmt(FREIFLAECHE.netzanschlussFixProMwp)} €/MWp`],
    ["Einschleifen MS-Leitung", `${fmt(N.einschleifen / 1000)} Tsd. €`],
    ["Schaltfeld Umspannwerk", `${fmt(N.uwFeld.min / 1000)}–${fmt(N.uwFeld.max / 1000)} Tsd. €`],
