                  { id: "jahr", label: "Je Jahr" },
                ]}
              />
            </div>
          }
        >
          {ansicht === "kumuliert" ? (
            <Linien
              xLabels={["0", ...r.szenarien[0].jahre.map((j) => String(j.jahr))]}
