import RechnerSeite, { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import ReststromRechner from "@/components/Reststrom/ReststromRechner";
import { STROM, STAND } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";
import { FAQ_RESTSTROM } from "@/data/faq";
import { pfad as seitenPfad } from "@/lib/land";
import { seitenLand, seitenMetadata } from "@/lib/land/seite";
import { faqFuerLand, NurDEBlock } from "@/components/Land/Laenderteile";

const PFAD = seitenPfad("/rechner/reststrom");

const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Reststrom-Rechner: Strompool-Ersparnis | ÖkoInvest",
  description:
    "Jahresverbrauch, Arbeitspreis und Lastprofil eingeben: Der Rechner zeigt, was Bündelung, Solar-PPA und Flexibilität im Reststrom-Pool pro Jahr sparen können.",
  keywords: ["Reststrom", "Strompool Mittelstand", "Gewerbestrom Ersparnis", "Strombeschaffung Rechner", "Solar-PPA", "Stromsteuer 2026"],
});

const ct2 = (n) => fmt(n, 2);
const fix = STROM.bestandteile.filter((b) => !b.beeinflussbar);

export default async function ReststromRechnerPage({ params }) {
  const land = await seitenLand(params);
  return (
    <RechnerSeite
      pfad={PFAD}
      toolId="reststrom"
      breadcrumb="Reststrom-Rechner"
      eyebrow="Reststrom-Rechner · Unternehmen"
      title={
        <>
          Was spart Ihr Betrieb im <span className="ov-text-gradient-light">Strompool?</span>
        </>
      }
      lead="Verbrauch, Preis und Lastprofil eingeben – Sie sehen die Ersparnisspanne je Hebel und wie sich Ihr Strompreis vorher und nachher zusammensetzt. Ehrlich gerechnet: Netzentgelte, Umlagen und Steuern bleiben, wie sie sind."
      chips={["Spanne je Hebel", "Preiszerlegung vorher/nachher", "Mit eigener PV", "Stromsteuer 2026"]}
      app={{
        name: "Reststrom-Rechner – Ersparnis im Strompool",
        description: "Schätzt die jährliche Ersparnis durch Bündelung, Solar-PPA und Flexibilität für den Reststrom mittelständischer Unternehmen.",
        featureList: ["Ersparnis je Hebel", "Preiszerlegung vorher/nachher", "Berücksichtigung eigener PV", "Stromsteuer-Entlastung produzierendes Gewerbe"],
      }}
      rechner={<ReststromRechner />}
      erklaerung={
        <NurDEBlock land={land} thema="Rechenwerte und Annahmen">
          <div className="ov-prose">
            <h2>So rechnet der Reststrom-Rechner</h2>
            <p>
              Ihr Arbeitspreis besteht aus zwei Welten. Fest vorgegeben sind Netzentgelte und Messung, Umlagen, Konzessionsabgabe und Stromsteuer – zusammen
              nach unserer Einschätzung für 2026 rund {fmt(fix.reduce((s, b) => s + b.ct, 0), 1)} ct/kWh. Was darüber liegt, ist Beschaffung und Vertrieb.
              Nur dort setzt der Pool an.
            </p>
            <p>Drei Hebel wirken auf diese Beschaffungskomponente:</p>
            <ul>
              {STROM.poolHebel.map((h) => (
                <li key={h.id}>
                  <strong>{h.label}</strong>: {ct2(h.ct.min)}–{ct2(h.ct.max)} ct/kWh
                </li>
              ))}
            </ul>
            <p>
              Wie viel davon bei Ihnen ankommt, hängt vom Lastprofil ab: Ein Einschichtbetrieb braucht Strom genau dann, wenn die Parks liefern – der PPA-Hebel ist
              groß. Ein Dreischichtbetrieb verbraucht viel nachts, profitiert dafür stärker von der strukturierten Beschaffung. Eine eigene PV-Anlage senkt Ihren
              Reststrom und deckt Tagesstunden bereits selbst – der PPA-Hebel wird kleiner, das Profil für den Pool aber planbarer.
            </p>
            <p>
              Damit das Ergebnis nicht zu optimistisch wird, deckelt der Rechner die Summe der Hebel bei gut einem Drittel Ihrer heutigen Beschaffungskomponente.
            </p>
          </div>
        </NurDEBlock>
      }
      annahmen={[
        ...STROM.bestandteile.map((b) => [b.label, `${ct2(b.ct)} ct/kWh`]),
        ["Stromsteuer produzierendes Gewerbe (ab 2026)", `${ct2(STROM.stromsteuerProduzierend)} ct/kWh`],
        ...STROM.poolHebel.map((h) => [h.label, `${ct2(h.ct.min)}–${ct2(h.ct.max)} ct`]),
        ["PPA-Deckung der Tagesstunden", `${fmt(STROM.ppaDeckungsanteil.min * 100)}–${fmt(STROM.ppaDeckungsanteil.max * 100)} %`],
        ["Stand", STAND],
      ]}
      quellen={[
        { name: "BDEW-Strompreisanalyse", url: "https://www.bdew.de/service/daten-und-grafiken/bdew-strompreisanalyse/" },
        { name: "Stromsteuergesetz", url: "https://www.gesetze-im-internet.de/stromstg/" },
        { name: "eigene Einschätzung ÖkoInvest" },
      ]}
      faq={faqFuerLand(FAQ_RESTSTROM.slice(0, 7), land)}
      faqTitel="Fragen zum Reststrom-Pool"
      querverweise={[
        { href: seitenPfad("/reststrom"), titel: "Reststrom-Pool Mittelstand", text: "Ablauf, Voraussetzungen und Zusammenspiel mit PV und Speicher." },
        { href: seitenPfad("/virtuelles-kraftwerk"), titel: "Virtuelles Kraftwerk", text: "Wie Parks, Speicher und Unternehmen im Verbund zusammenwirken." },
        { href: seitenPfad("/energie-live"), titel: "Strommarkt live", text: "Börsenpreis, negative Preise und Solar-Capture-Rate in Echtzeit." },
      ]}
      cta={{
        eyebrow: "Reststrom-Pool",
        title: "Aus der Spanne wird ein Angebot.",
        text: "Schicken Sie uns Lastgang oder Jahresverbrauch und Ihren aktuellen Vertrag. Wir prüfen Profil, Kündigungsfristen und Preisbestandteile – kostenlos und unverbindlich.",
        primary: { label: "Pool-Angebot anfragen", href: seitenPfad("/reststrom#anfrage") },
        secondary: { label: "Wie der Pool funktioniert", href: seitenPfad("/reststrom") },
      }}
    />
  );
}

export const generateMetadata = seitenMetadata("/rechner/reststrom", metadata);
"use client";

import { useMemo, useState } from "react";
import { AlertTriangle, Factory, Info, Landmark, PiggyBank, Sun, Zap } from "lucide-react";
import { Auswahl, Belege, Gruppe, Hauptzahl, Kennzahl, Regler, Schalter, Zahl } from "@/components/Rechner/bausteine";
import { useTeilbarerZustand } from "@/components/Rechner/kontext";
import { ErgebnisKopf, MobilKurz, RechnerRahmen } from "@/components/Rechner/InvestTeile";
import AnfrageFormular from "@/components/Plattform/AnfrageFormular";
import PreisBalken from "./PreisBalken";
import { berechneReststrom, LASTPROFILE, PV_ERTRAG_KWH_PRO_KWP, SINNVOLL_AB_MWH } from "@/lib/rechner/reststrom";
import { fmt, fmtEur } from "@/lib/rechner/annahmen";
import { cn } from "@/components/ui/cn";

// auf 100 € gerundet – mehr Genauigkeit gibt eine Spanne nicht her
const eurK = (n) => fmtEur(Math.round(n / 100) * 100);

export default function ReststromRechner() {
  const [verbrauch, setVerbrauch] = useState(500);
  const [preis, setPreis] = useState(22);
  const [profil, setProfil] = useState("einschicht");
  const [pvAn, setPvAn] = useState(false);
  const [pvKwp, setPvKwp] = useState(250);
  const [pvStatus, setPvStatus] = useState("geplant");
  const [produzierend, setProduzierend] = useState(false);

  const r = useMemo(
    () =>
      berechneReststrom({
        verbrauchMwh: verbrauch,
        preisCt: preis,
        profil,
        pvKwp: pvAn ? pvKwp : 0,
        pvBestand: pvAn && pvStatus === "bestand",
        produzierend,
      }),
    [verbrauch, preis, profil, pvAn, pvKwp, pvStatus, produzierend]
  );

  // Teilen-Link: Eingaben in der Adresszeile (nur Abweichungen vom Standard)
  const SETZER = { verbrauch: setVerbrauch, preis: setPreis, profil: setProfil, pvAn: setPvAn, pvKwp: setPvKwp, pvStatus: setPvStatus, produzierend: setProduzierend };
  useTeilbarerZustand(
    { verbrauch, preis, profil, pvAn, pvKwp, pvStatus, produzierend },
    (neu) => Object.entries(neu).forEach(([k, v]) => SETZER[k]?.(v)),
    {
      optionen: { profil: LASTPROFILE.map((l) => l.id), pvStatus: ["geplant", "bestand"] },
      grenzen: { verbrauch: [20, 5000], preis: [12, 40], pvKwp: [10, 2000] },
    }
  );

  const maxHebel = Math.max(...r.hebel.map((h) => h.eurMax), 1);
  const skala = Math.max(preis, r.fixSumme + 1);

  return (
    <RechnerRahmen
      breiteLinks={400}
      eingaben={
        <>
          <MobilKurz
            werte={[
              ["Ersparnis/Jahr", `${eurK(r.gesamt.eurMin)} – ${eurK(r.gesamt.eurMax)}`],
              ["je kWh", `${fmt(r.gesamt.ctMin, 1)}–${fmt(r.gesamt.ctMax, 1)} ct`],
              ["Reststrom", `${fmt(r.reststromKwh / 1000)} MWh`],
            ]}
          />
          <Gruppe titel="Ihr Strombezug">
            <Regler
              label="Jahresverbrauch aus dem Netz"
              wert={verbrauch}
              min={20}
              max={5000}
              step={10}
              einheit="MWh"
              onChange={setVerbrauch}
              hinweis="Steht auf der Jahresabrechnung (1 MWh = 1.000 kWh)."
            />
            <Regler
              label="Aktueller Arbeitspreis, netto"
              wert={preis}
              min={12}
              max={40}
              step={0.1}
              stellen={1}
              einheit="ct/kWh"
              onChange={setPreis}
              hinweis="Gesamtpreis je kWh inkl. Netzentgelten, Umlagen und Stromsteuer, ohne Umsatzsteuer und Grundpreis."
            />
          </Gruppe>

          <Gruppe titel="Betrieb" className="mt-8">
            <Auswahl legende="Lastprofil" optionen={LASTPROFILE} wert={profil} onChange={setProfil} spalten={2} />
            <Schalter
              label="Eigene PV-Anlage"
              beschreibung="Vorhanden oder geplant, z. B. von ÖKOVOLT"
              an={pvAn}
              onChange={setPvAn}
              icon={Sun}
            >
              <div className="space-y-5">
                <Regler label="Leistung" wert={pvKwp} min={10} max={2000} step={10} einheit="kWp" onChange={setPvKwp} />
                <Auswahl
                  legende="Status"
                  klein
                  optionen={[
                    { id: "geplant", label: "geplant", sub: "senkt den Bezug" },
                    { id: "bestand", label: "läuft schon", sub: "Verbrauch = Reststrom" },
                  ]}
                  wert={pvStatus}
                  onChange={setPvStatus}
                />
              </div>
            </Schalter>
            <Schalter
              label="Produzierendes Gewerbe"
              beschreibung="oder Land- und Forstwirtschaft (Stromsteuer)"
              an={produzierend}
              onChange={setProduzierend}
              icon={Factory}
            />
          </Gruppe>
        </>
      }
      ergebnis={
        <>
          <p className="sr-only" aria-live="polite">
            {`Ersparnis im Pool ${eurK(r.gesamt.eurMin)} bis ${eurK(r.gesamt.eurMax)} pro Jahr, ${fmt(r.gesamt.ctMin, 1)} bis ${fmt(r.gesamt.ctMax, 1)} Cent je Kilowattstunde.`}
          </p>
          <ErgebnisKopf titel="Ihre Ersparnis im Pool" plakette={`${fmt(verbrauch)} MWh · ${fmt(preis, 1)} ct/kWh`} />
          <Hauptzahl className="mt-5" icon={PiggyBank} label="Ersparnis Pool pro Jahr" zusatz={`Mitte ca. ${eurK(r.gesamt.eurMitte)}`}>
            <Zahl wert={Math.round(r.gesamt.eurMin / 100) * 100} /> – <Zahl wert={Math.round(r.gesamt.eurMax / 100) * 100} suffix=" €" />
          </Hauptzahl>

          <Belege>
            <Kennzahl label="je kWh Reststrom" ton="akzent" icon={Zap} zusatz={`${fmt(r.gesamt.anteilMin * 100, 0)}–${fmt(r.gesamt.anteilMax * 100, 0)} % der Stromkosten`}>
              <Zahl wert={r.gesamt.ctMin} stellen={1} />–<Zahl wert={r.gesamt.ctMax} stellen={1} suffix=" ct" />
            </Kennzahl>
            <Kennzahl label="Reststrom für den Pool" ton="sand" zusatz={r.eigenverbrauch > 0 ? `nach ca. ${fmt(r.eigenverbrauch / 1000, 0)} MWh Eigenverbrauch` : "gesamter Netzbezug"}>
              <Zahl wert={r.reststromKwh / 1000} suffix=" MWh" />
            </Kennzahl>
            <Kennzahl label="Stromkosten heute (Reststrom)" ton="sand" zusatz="netto, ohne Grundpreis">
              <Zahl wert={Math.round(r.kostenVorher / 100) * 100} suffix=" €" />
            </Kennzahl>
          </Belege>

          {/* Hebel */}
          <h3 className="mt-8 font-display text-[18px] font-bold text-ink-900">Ersparnis je Hebel</h3>
          <ul className="mt-4 space-y-4">
            {r.hebel.map((h) => (
              <li key={h.id}>
                <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 text-[14px]">
                  <span className="font-semibold text-ink-800">{h.label}</span>
                  <span className="ov-num text-ink-600">
                    {fmt(h.ctMin, 2)}–{fmt(h.ctMax, 2)} ct · <strong className="text-ink-900">{eurK(h.eurMin)} – {eurK(h.eurMax)}</strong>
                  </span>
                </div>
                <div className="relative mt-2 h-3 rounded-full bg-ink-100" aria-hidden="true">
                  <div
                    className="absolute inset-y-0 rounded-full bg-ov-500/80 transition-all duration-500"
                    style={{ left: `${(h.eurMin / maxHebel) * 100}%`, width: `${Math.max(((h.eurMax - h.eurMin) / maxHebel) * 100, 1)}%` }}
                  />
                  <div className="absolute inset-y-0 left-0 rounded-full bg-ov-200 transition-all duration-500" style={{ width: `${(h.eurMin / maxHebel) * 100}%` }} />
                </div>
              </li>
            ))}
          </ul>

          {/* Preiszerlegung */}
          <h3 className="mt-9 font-display text-[18px] font-bold text-ink-900">Preiszerlegung vorher / nachher</h3>
          <p className="mt-1 text-[13.5px] text-ink-500">Nachher mit der Mitte der Spanne. Nur die grüne Beschaffungskomponente ändert sich, die schraffierte Fläche ist die Ersparnis je kWh.</p>
          <PreisBalken
            className="mt-5"
            max={skala}
            ersparnis
            zeilen={[
              { titel: "Heute (Einzelvertrag)", teile: r.vorher },
              { titel: "Mit Reststrom-Pool", teile: r.nachher },
            ]}
          />

          {/* Hinweise */}
          <div className="mt-8 space-y-3">
            {r.stromsteuer && (
              <p className="flex gap-3 rounded-2xl bg-navy-50 p-4 text-[14px] leading-relaxed text-navy-900 ring-1 ring-navy-100">
                <Landmark aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-navy-600" />
                <span>
                  <strong>Zusätzlich: Stromsteuer-Entlastung.</strong> Als produzierendes Gewerbe zahlen Sie seit 2026 nur noch den EU-Mindestsatz. Das sind
                  weitere rund <strong>{eurK(r.stromsteuer.eur)}</strong> pro Jahr ({fmt(r.stromsteuer.ctJeKwh, 2)} ct/kWh) – falls noch nicht beantragt.
                  Die Entlastung wird beim Hauptzollamt beantragt und ist keine Leistung des Pools.
                </span>
              </p>
            )}
            {r.klein && (
              <p className="flex gap-3 rounded-2xl bg-sun-400/10 p-4 text-[14px] leading-relaxed text-ink-800 ring-1 ring-sun-400/30">
                <AlertTriangle aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-sun-500" />
                Unter etwa {fmt(SINNVOLL_AB_MWH)} MWh ist der Hebel meist kleiner als die Kosten der strukturierten Beschaffung. Wir prüfen Ihren Fall trotzdem gern.
              </p>
            )}
            {r.preisUnplausibel && (
              <p className="flex gap-3 rounded-2xl bg-sun-400/10 p-4 text-[14px] leading-relaxed text-ink-800 ring-1 ring-sun-400/30">
                <AlertTriangle aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-sun-500" />
                Ihr Preis liegt kaum über Netzentgelten, Umlagen und Steuern (rund {fmt(r.fixSumme, 1)} ct/kWh). Prüfen Sie, ob wirklich der Gesamtpreis gemeint ist –
                oder Sie haben bereits sehr gut eingekauft.
              </p>
            )}
            <p className="flex gap-3 text-[13px] leading-relaxed text-ink-500">
              <Info aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0" />
              Orientierung, kein Angebot. PV-Ertrag vereinfacht mit {fmt(PV_ERTRAG_KWH_PRO_KWP)} kWh/kWp. Die tatsächliche Ersparnis hängt von Lastgang, Marktlage
              zum Beschaffungszeitpunkt und Vertragslaufzeit ab.
            </p>
          </div>
        </>
      }
      unten={
        <details className="group rounded-3xl bg-sand-50 ring-1 ring-ink-200/70 open:bg-white">
          <summary className={cn("flex min-h-14 cursor-pointer list-none items-center justify-between gap-4 px-5 py-4 font-display text-[17px] font-bold text-ink-900 [&::-webkit-details-marker]:hidden")}>
            Mit diesen Werten ein Angebot anfragen
            <span className="rounded-full bg-ov-600 px-4 py-2 text-[13.5px] font-semibold text-white group-open:hidden">Öffnen</span>
          </summary>
          <div className="px-5 pb-6">
            <AnfrageFormular
              typ="reststrom"
              felder={["firma", "telefon", "plz", "nachricht"]}
              button="Pool-Angebot anfragen"
              daten={{
                quelle: "rechner-reststrom",
                verbrauchMwh: verbrauch,
                arbeitspreisCt: preis,
                lastprofil: profil,
                pvKwp: pvAn ? pvKwp : 0,
                pvStatus: pvAn ? pvStatus : null,
                produzierendesGewerbe: produzierend,
                ersparnisEurMin: Math.round(r.gesamt.eurMin),
                ersparnisEurMax: Math.round(r.gesamt.eurMax),
              }}
            />
          </div>
        </details>
      }
    />
  );
}
src/app/(stamm)/rechner/reststrom/page.js:2:import ReststromRechner from "@/components/Reststrom/ReststromRechner";

  button: buttonProp,
  erfolgText: erfolgProp,
  rolle,
  className,
  dunkel = false,
