                ].map((x) => (
                  <div key={x.label}>
                    <dt className="sr-only">{x.label}</dt>
                    <dd className="font-display text-[clamp(1.5rem,1.1rem+1.4vw,2.25rem)] font-extrabold leading-none tracking-tight text-white">
                      <CountUp value={x.value} suffix={x.suffix} />
                    </dd>
                    <dd className="mt-2 text-[13px] leading-snug text-white/65">{x.label}</dd>
                  </div>
                ))}
              </dl>
            </div>

            <figure className="ov-hero-in relative max-sm:hidden sm:px-6 lg:px-0" style={{ "--ov-delay": "220ms" }}>
              <div aria-hidden="true" className="pointer-events-none absolute -inset-x-8 -inset-y-12 -z-10 rounded-full bg-[radial-gradient(closest-side,rgba(140,186,88,0.22),transparent_70%)] blur-2xl" />
              <HubBuehne park={park} cashflow={cf} />
              <figcaption className="mt-6 text-center text-[12px] text-white/60 sm:mt-16 lg:text-right">
                {/* Beispielwerte der Bühne = deutsche Standardannahmen: gemeinsam mit Vermerk, in AT/CH ausdrücklich als deutsches Beispiel */}
                {!land || land === "DE" ? t.buehneGemeinsam(!land) : t.buehneLand(land)}
              </figcaption>
            </figure>
          </div>
        </div>
      </section>

      <section id="werkzeuge" aria-label={t.alleAria} className="relative z-10 -mt-20 scroll-mt-20 md:-mt-28">
        <div className="ov-container">
          <div className="divide-y divide-ink-100 rounded-[2rem] bg-white px-5 shadow-[0_40px_80px_-40px_rgba(3,18,43,0.45)] ring-1 ring-ink-200/70 sm:px-6 md:px-8">
            {/* Sprungnavigation: in einem Tipp zur eigenen Zielgruppe */}
            <nav aria-label={t.zielgruppeAria} className="ov-no-scrollbar -mx-5 flex items-center gap-2 overflow-x-auto px-5 py-5 sm:mx-0 sm:flex-wrap sm:px-0">
              <span className="mr-1 text-[12px] font-bold uppercase tracking-[0.16em] text-ink-500">{t.fuer}</span>
              {gruppen.map((g) => (
                <a
                  key={g.id}
                  href={`#${g.id}`}
                  className="inline-flex min-h-10 shrink-0 items-center gap-2 whitespace-nowrap rounded-full bg-sand-50 px-4 text-[14px] font-semibold text-ink-800 ring-1 ring-ink-200/70 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500"
                >
                  {g.kurz}
                  <span className="ov-num rounded-full bg-white px-1.5 text-[12px] font-bold text-ink-500 ring-1 ring-ink-200/70">{g.ids.length + g.weitere.length}</span>
                </a>
              ))}
            </nav>
            {gruppen.map((g) => (
              <section key={g.id} id={g.id} aria-labelledby={`${g.id}-titel`} className="scroll-mt-28 py-8 md:py-10">
                <div className="mb-6 flex flex-wrap items-end justify-between gap-x-6 gap-y-1">
                  <h2 id={`${g.id}-titel`} className="ov-h3 text-ink-900 md:text-[26px]">
                    {g.titel}
                  </h2>
                  <p className="text-[14.5px] text-ink-500">{g.text}</p>
                </div>
                <ul className={cn("grid gap-4 lg:gap-5", g.ids.length === 2 ? "md:grid-cols-2" : "md:grid-cols-2 lg:grid-cols-3")}>
                  {g.ids.map((id, i) => {
                    const tool = toolById(id);
                    if (!tool) return null;
                    return (
                      <Reveal as="li" key={id} delay={i * 60} className="flex">
                        <ToolKarte tool={tool} tagText={tagText(tool.tag)} oeffnen={t.oeffnen} ton={id === "solarpark" ? "dunkel" : "hell"} gross={g.ids.length === 2}>
                          {vorschauImLand[id]}
                        </ToolKarte>
                      </Reveal>
                    );
                  })}
                </ul>
                {g.weitere.length > 0 && (
                  <ul suppressHydrationWarning className={cn("ov-reveal ov-stagger mt-4 grid gap-3 md:grid-cols-2 lg:mt-5", g.weitere.length % 3 === 0 && "lg:grid-cols-3")} aria-label={t.weitereAria(g.kurz)}>
                    {g.weitere.map((id) => {
                      const tool = toolById(id);
                      if (!tool) return null;
                      return (
                        <li key={id} className="flex">
                          <ToolZeile tool={tool} tagText={tagText(tool.tag)} />
                        </li>
                      );
                    })}
                  </ul>
                )}
              </section>
            ))}
          </div>
        </div>
      </section>

      <Section tone="white" space="md" id="wegweiser" className="scroll-mt-20">
        <div className="flex flex-wrap items-end justify-between gap-x-10 gap-y-4">
          <SectionHeading eyebrow={t.wegEyebrow} title={t.wegTitel} className="max-w-2xl" />
          <p className="max-w-md text-pretty text-[15.5px] leading-relaxed text-ink-600 [hyphens:manual] lg:pb-2">{t.wegText}</p>
        </div>
        <ul suppressHydrationWarning className="ov-reveal ov-stagger mt-10 grid gap-3 sm:grid-cols-2 lg:mt-12 lg:grid-cols-4">
          {t.wegweiser.map(([frage, id, ergebnis]) => {
            const tool = toolById(id);
            if (!tool) return null;
            const Icon = tool.icon;
            return (
              <li key={id} className="flex">
                <Link
                  href={tool.href}
                  className="group ov-lift flex w-full flex-col gap-4 rounded-2xl bg-white p-5 ring-1 ring-ink-200/70 transition-colors hover:ring-ov-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500"
                >
                  <span className="flex items-start justify-between gap-3">
                    <span className="font-display text-[16.5px] font-bold leading-snug text-ink-900">{frage}</span>
                    <ArrowUpRight aria-hidden="true" className="mt-1 h-4 w-4 shrink-0 text-ink-400 transition-transform duration-200 group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-ov-700 motion-reduce:transition-none" />
                  </span>
                  <span className="mt-auto flex items-center gap-2.5 border-t border-ink-100 pt-3.5">
                    <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-ov-50 text-ov-600 ring-1 ring-ov-100 transition-colors group-hover:bg-ov-600 group-hover:text-white group-hover:ring-ov-600">
                      <Icon aria-hidden="true" className="h-4 w-4" />
                    </span>
                    <span className="min-w-0">
                      <span className="block truncate text-[13.5px] font-semibold text-ov-700">{tool.titel}</span>
                      <span className="block truncate text-[12.5px] text-ink-500">{ergebnis}</span>
                    </span>
                  </span>
                </Link>
              </li>
            );
          })}
        </ul>
      </Section>

      <Section tone="sand" space="md">
        <div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading eyebrow={t.faqEyebrow} title={t.faqTitel} lead={t.faqLead} />
          <Faq items={t.faq} />
        </div>
      </Section>

      <CtaBand eyebrow={t.cta.eyebrow} title={t.cta.title} text={t.cta.text} primary={t.cta.primary} secondary={t.cta.secondary} />
    </div>
  );
}

function ToolKarte({ tool, tagText, oeffnen, ton, gross, children }) {
  const Icon = tool.icon;
  const dunkel = ton === "dunkel";
  return (
    <Link
      href={tool.href}
      className={cn(
        "group ov-lift flex w-full flex-col rounded-3xl p-6 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2 md:p-7",
        dunkel ? "ov-verlauf-nacht text-white ring-1 ring-white/10 shadow-kante" : "bg-sand-50 ring-1 ring-ink-200/70 hover:bg-white hover:ring-ov-300"
      )}
    >
      <div className="flex items-start justify-between gap-4">
        <span className={cn("flex h-12 w-12 items-center justify-center rounded-2xl", dunkel ? "bg-white/10 text-ov-300 ring-1 ring-white/15" : "bg-ov-50 text-ov-600 ring-1 ring-ov-100")}>
          <Icon aria-hidden="true" className="h-6 w-6" />
        </span>
        {tool.tag && <span className={cn("rounded-full px-2.5 py-1 text-[11.5px] font-bold", dunkel ? "bg-sun-300 text-navy-950" : TAG_TON[tool.tag] || "bg-ink-100 text-ink-700")}>{tagText}</span>}
      </div>
      <h3 className={cn("mt-5 font-display font-extrabold leading-tight tracking-tight", gross ? "text-[24px]" : "text-[20px]", dunkel ? "text-white" : "text-ink-900")}>{tool.titel}</h3>
      <p className={cn("mt-2 text-[14.5px] leading-relaxed", dunkel ? "text-white/75" : "text-ink-600")}>{gross ? tool.text : tool.kurz}</p>
      <div className="mt-6 flex flex-1 flex-col">
        <div className={cn("flex min-h-[150px] flex-1 flex-col justify-center rounded-2xl bg-white p-4", dunkel ? "shadow-e3" : "shadow-e1 ring-1 ring-ink-200/60")}>{children}</div>
      </div>
      <span className={cn("mt-5 inline-flex items-center gap-1.5 text-[14.5px] font-semibold", dunkel ? "text-ov-300" : "text-ov-700")}>
        {oeffnen}
        <ArrowUpRight aria-hidden="true" className="h-4 w-4 transition-transform duration-300 group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
      </span>
    </Link>
  );
}

/** Kompakte Tool-Zeile für weitere Werkzeuge einer Zielgruppe */
function ToolZeile({ tool, tagText }) {
  const Icon = tool.icon;
  return (
    <Link
      href={tool.href}
      className="group ov-lift flex w-full items-start gap-4 rounded-3xl bg-white p-5 ring-1 ring-ink-200/70 transition-colors hover:ring-ov-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500"
    >
      <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-ov-50 text-ov-600 ring-1 ring-ov-100 transition-colors group-hover:bg-ov-600 group-hover:text-white group-hover:ring-ov-600">
        <Icon aria-hidden="true" className="h-5 w-5" />
      </span>
      <span className="min-w-0 flex-1">
        <span className="flex flex-wrap items-center gap-x-2 gap-y-1">
          <span className="font-display text-[17px] font-bold leading-snug text-ink-900">{tool.titel}</span>
          {tool.tag && <span className={cn("rounded-full px-2 py-0.5 text-[11px] font-bold", TAG_TON[tool.tag] || "bg-ink-100 text-ink-700")}>{tagText}</span>}
        </span>
        <span className="mt-1 block text-[14px] leading-relaxed text-ink-600">{tool.kurz}</span>
      </span>
      <ArrowUpRight aria-hidden="true" className="mt-1 h-4 w-4 shrink-0 text-ink-500 transition-transform duration-200 group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-ov-700" />
    </Link>
  );
}

export const generateMetadata = seitenMetadata("/rechner", metadata, { en: metadataEn });

content.content:
// marktdaten/page.js – Marktdaten-Hub Freiflächen-PV (EEG-Ausschreibungen, Marktwert Solar, Capture Rate, Zubau, Pacht)

import Link from "@/components/Land/Link";
import { ArrowRight, BarChart3, Database, ExternalLink, Gavel, Sun, TrendingDown, Zap } from "lucide-react";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Reveal from "@/components/ui/Reveal";
import Querverweise from "@/components/Reusable/Querverweise";
import { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import AusschreibungsChart from "@/components/Marktdaten/AusschreibungsChart";
import MarktwertChart from "@/components/Marktdaten/MarktwertChart";
import LiveEinordnung from "@/components/Marktdaten/LiveEinordnung";
import Hero from "@/components/Marktdaten/Seite/Hero";
import Kennzahlen from "@/components/Marktdaten/Seite/Kennzahlen";
import { abs } from "@/data/site";
import {
  AUSSCHREIBUNGEN,
  AUSSCHREIBUNGEN_JAHR,
  MARKTWERTE,
  MARKTWERT_SOLAR_FRUEHER,
  NEGATIVE_STUNDEN,
  ZUBAU,
  MARKTDATEN_QUELLEN,
  MARKTDATEN_STAND,
  MARKTDATEN_STAND_TEXT,
  NAECHSTER_GEBOTSTERMIN,
  LETZTE_AUSSCHREIBUNG,
  LETZTER_MARKTWERT,
  MIN_ZUSCHLAG,
  MAX_ZUSCHLAG,
  SUMME_ZUSCHLAG_MW,
  LANDPACHT_DESTATIS,
} from "@/data/marktdaten";
import { PACHT, ERLOESE, FREIFLAECHE } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";
import { getEnergySnapshot } from "@/lib/energy";
import JsonLd from "@/components/JsonLd";
import { pfad as seitenPfad } from "@/lib/land";
import { seitenLand, seitenMetadata } from "@/lib/land/seite";
import { GiltFuer, LandHinweis } from "@/components/Land/LandHinweis";
import { faqFuerLand } from "@/components/Land/Laenderteile";

export const revalidate = 900;

const PFAD = seitenPfad("/marktdaten");
const PAGE_URL = abs(PFAD);

const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Marktdaten Solar: EEG-Zuschläge & Marktwert | ÖkoInvest",
  description:
    "Marktdaten Freiflächen-PV: EEG-Zuschlagswerte seit 2017, Höchstwerte, Gebotsmengen, Marktwert Solar, Capture Rate, Zubau DACH und Pacht – mit Quellen.",
  keywords: [
    "EEG Ausschreibung Solar Ergebnisse",
    "Zuschlagswert Solar Freifläche",
    "Marktwert Solar Jahresmarktwert",
    "Capture Rate Solar Deutschland",
    "Solarpark Marktdaten",
    "negative Strompreise Stunden",
    "PV Zubau Freifläche",
  ],
});

/* ------------------------------------------------------------------ */
/* Abgeleitete Aussagen                                                */
/* ------------------------------------------------------------------ */

const MONATE = ["Januar", "Februar", "März", "April", "Mai", "Juni", "Juli", "August", "September", "Oktober", "November", "Dezember"];
const termin = (iso) => `${Number(iso.slice(8, 10))}. ${MONATE[Number(iso.slice(5, 7)) - 1]} ${iso.slice(0, 4)}`;
const ct = (v, s = 2) => `${fmt(v, s)} ct/kWh`;
const L = LETZTE_AUSSCHREIBUNG;
const VORLETZTE = AUSSCHREIBUNGEN[AUSSCHREIBUNGEN.length - 2];
const JAHR_2025 = AUSSCHREIBUNGEN_JAHR.find((j) => j.jahr === 2025);
const MW_2020 = MARKTWERTE.find((m) => m.jahr === 2020);
const NEG_2025 = NEGATIVE_STUNDEN.find((n) => n.jahr === 2025);
const NEG_2022 = NEGATIVE_STUNDEN.find((n) => n.jahr === 2022);
const ERSTER = AUSSCHREIBUNGEN[0];
const SEIT_2024 = AUSSCHREIBUNGEN.filter((a) => a.datum >= "2024").reduce((r, a) => ({ min: Math.min(r.min, a.mittel), max: Math.max(r.max, a.mittel) }), { min: Infinity, max: -Infinity });
const faktorAcker = PACHT.freiflaecheProHa.mittel / LANDPACHT_DESTATIS.schnitt;

const ANTWORT = `Beim letzten Gebotstermin am ${termin(L.datum)} lag der mengengewichtete Zuschlagswert für Freiflächen-Solaranlagen bei ${ct(L.mittel)} (Vorrunde: ${ct(VORLETZTE.mittel)}). Seit ${ERSTER.datum.slice(0, 4)} schwankten die Ergebnisse zwischen ${ct(MIN_ZUSCHLAG.mittel)} (${termin(MIN_ZUSCHLAG.datum)}) und ${ct(MAX_ZUSCHLAG.mittel)} (${termin(MAX_ZUSCHLAG.datum)}).`;

const KENNZAHLEN = [
  // zahl/stellen: dieselben Werte wie `wert`, als Zahl für den Count-up (nur Werte, die auf der Seite stehen)
  { icon: Gavel, wert: fmt(L.mittel, 2), zahl: Number(L.mittel.toFixed(2)), stellen: 2, einheit: "ct/kWh", text: `Ø Zuschlag Solar, ${termin(L.datum)}` },
  { icon: BarChart3, wert: fmt(L.gebote / L.volumen, 1), zahl: Number((L.gebote / L.volumen).toFixed(1)), stellen: 1, einheit: "fach", text: `überzeichnet im ${MONATE[Number(L.datum.slice(5, 7)) - 1]} ${L.datum.slice(0, 4)}` },
  { icon: Sun, wert: fmt(LETZTER_MARKTWERT.capture * 100), zahl: Math.round(LETZTER_MARKTWERT.capture * 100), stellen: 0, einheit: "%", text: `Capture Rate Solar ${LETZTER_MARKTWERT.jahr}` },
  { icon: TrendingDown, wert: fmt(NEG_2025.stunden), zahl: Math.round(NEG_2025.stunden), stellen: 0, einheit: "h", text: `Stunden mit negativem Preis ${NEG_2025.jahr}` },
];

const PHASEN_TEXT = [
  {
    titel: "2017–2021: Kostenverfall und stabiler Wettbewerb",
    text: `Von ${ct(ERSTER.mittel)} im Februar 2017 fielen die Zuschläge binnen eines Jahres auf ${ct(4.33)}. Danach pendelten sie sich – mit Ausreißern bei den Sonderausschreibungen 2019 – um 5 ct ein – bei zunächst kleinen Ausschreibungsmengen von 100 bis 600 MW je Termin.`,
  },
  {
    titel: "2022–2023: Zinswende, Lieferketten, höherer Höchstwert",
    text: "2022 blieben einzelne Runden unterzeichnet, die Zuschläge stiegen bis an den Höchstwert. Die Bundesnetzagentur hob den Höchstwert für 2023 auf 7,37 ct an – im März 2023 lag der Durchschnitt mit 7,03 ct auf dem höchsten Stand seit 2017.",
  },
  {
    titel: "Seit 2024: große Volumen, starker Wettbewerb",
    text: `Mit Ausschreibungsmengen von über 2 GW je Termin und deutlicher Überzeichnung liegen die Ergebnisse wieder zwischen ${fmt(SEIT_2024.min, 2)} und ${fmt(SEIT_2024.max, 2)} ct. 2025 wurden in drei Runden zusammen rund ${fmt(JAHR_2025.zuschlag / 1000, 1)} GW bezuschlagt, im Mittel ${ct(JAHR_2025.mittel)}.`,
  },
];

const FAQ = [
  {
    q: "Wie hoch ist der aktuelle Zuschlagswert für Freiflächen-Solaranlagen?",
    a: `Beim Gebotstermin am ${termin(L.datum)} lag der mengengewichtete durchschnittliche Zuschlagswert bei ${ct(L.mittel)}; bezuschlagt wurden Gebote zwischen ${ct(L.min)} und ${ct(L.max)}. Der Höchstwert betrug ${ct(L.hoechst)}. Der nächste reguläre Gebotstermin ist der ${NAECHSTER_GEBOTSTERMIN}.`,
    nurDE: true,
  },
  {
    q: "Was bedeutet „mengengewichteter Zuschlagswert“?",
    a: "Jeder bezuschlagte Bieter erhält seinen eigenen Gebotswert (Pay-as-bid). Der mengengewichtete Durchschnitt gewichtet diese Werte mit der jeweiligen Leistung – große Parks zählen also stärker als kleine. Er ist die übliche Kennzahl, um Gebotstermine zu vergleichen.",
  },
  {
    q: "Was ist der Unterschied zwischen Zuschlagswert und Marktwert Solar?",
    a: "Der Zuschlagswert ist der anzulegende Wert, den ein Park über 20 Jahre als Untergrenze seiner Erlöse erhält – die Differenz zum Marktwert zahlt das EEG-Konto als Marktprämie. Der Marktwert Solar ist das, was Solarstrom an der Börse tatsächlich im Schnitt erlöst. Liegt der Marktwert über dem Zuschlagswert, entfällt die Prämie.",
  },
  {
    q: "Was ist die Capture Rate und warum sinkt sie?",
    a: `Die Capture Rate setzt den Jahresmarktwert Solar ins Verhältnis zum durchschnittlichen Börsenpreis. ${LETZTER_MARKTWERT.jahr} lag sie bei rund ${fmt(LETZTER_MARKTWERT.capture * 100)} %, ${MW_2020.jahr} noch bei ${fmt(MW_2020.capture * 100)} %. Weil immer mehr Solaranlagen gleichzeitig mittags einspeisen, sinkt der Preis genau dann, wenn Solarparks produzieren (Kannibalisierung).`,
    nurDE: true,
  },
  {
    q: "Wie oft gab es negative Strompreise?",
    a: `Nach Auswertung von Energy-Charts-Daten gab es ${NEG_2025.jahr} rund ${fmt(NEG_2025.stunden)} Stunden mit negativem Day-Ahead-Preis, ${NEG_2022.jahr} waren es nur ${fmt(NEG_2022.stunden)}. Für neue Anlagen entfällt in diesen Zeiten die Marktprämie; Speicher und flexible Abnehmer gewinnen deshalb an Wert.`,
    nurDE: true,
  },
  {
    q: "Wie aktuell sind die Marktdaten und woher stammen sie?",
    a: `Stand der Seite: ${MARKTDATEN_STAND_TEXT}. Ausschreibungsergebnisse stammen von der Bundesnetzagentur, Marktwerte von den Übertragungsnetzbetreibern (netztransparenz.de), negative Stunden aus Energy-Charts (Fraunhofer ISE), Zubauzahlen von Bundesnetzagentur, PV Austria und Swissolar. Den Börsenpreis zeigen wir live. Alle Angaben ohne Gewähr.`,
  },
];

const QUERVERWEISE = [
  { href: "/ratgeber/eeg-ausschreibung-freiflaeche", titel: "EEG-Ausschreibung Freifläche", text: "Termine, Voraussetzungen, Sicherheiten und Gebotsstrategie." },
  { href: seitenPfad("/rechner/solarpark"), titel: "Solarpark-Renditerechner", text: "IRR und Cashflow mit Zuschlagswert, PPA oder Marktwert rechnen." },
  { href: seitenPfad("/energie-live"), titel: "Strommarkt live", text: "Day-Ahead-Preis, Strommix und Capture Rate von heute." },
  { href: "/projektboerse", titel: "Projektbörse", text: "Solarprojekte in allen Phasen finden oder anbieten." },
];

/* ------------------------------------------------------------------ */
/* JSON-LD                                                             */
/* ------------------------------------------------------------------ */

const datasetSchema = {
  "@context": "https://schema.org",
  "@type": "Dataset",
  "@id": `${PAGE_URL}/#dataset`,
  name: "Marktdaten Freiflächen-Photovoltaik: EEG-Ausschreibungen Solar erstes Segment, Marktwert Solar und Capture Rate",
  description:
    "Ergebnisse aller Gebotstermine der EEG-Ausschreibungen für Solaranlagen des ersten Segments seit 2017 (Volumen, Gebotsmenge, Zuschlagsmenge, mengengewichteter Zuschlagswert, Spanne, Höchstwert), Jahresmarktwerte Spot und Solar mit Capture Rate seit 2020, Stunden mit negativen Strompreisen sowie Photovoltaik-Zubau in Deutschland, Österreich und der Schweiz.",
  url: PAGE_URL,
  keywords: ["EEG-Ausschreibung", "Photovoltaik", "Freiflächenanlagen", "Zuschlagswert", "Marktwert Solar", "Capture Rate", "negative Strompreise", "DACH"],
  isAccessibleForFree: true,
  inLanguage: "de",
  creator: { "@type": "Organization", name: "ÖkoInvest GmbH", url: abs("/") },
  publisher: { "@id": `${abs("/")}/#organization` },
  isBasedOn: MARKTDATEN_QUELLEN.map((q) => q.url),
  spatialCoverage: [
    { "@type": "Place", name: "Deutschland" },
    { "@type": "Place", name: "Österreich" },
    { "@type": "Place", name: "Schweiz" },
  ],
  temporalCoverage: `${ERSTER.datum}/${L.datum}`,
  dateModified: MARKTDATEN_STAND,
  variableMeasured: [
    { "@type": "PropertyValue", name: "Mengengewichteter durchschnittlicher Zuschlagswert", unitText: "ct/kWh" },
    { "@type": "PropertyValue", name: "Höchstwert je Gebotstermin", unitText: "ct/kWh" },
    { "@type": "PropertyValue", name: "Ausgeschriebene Menge, Gebotsmenge, Zuschlagsmenge", unitText: "MW" },
