(r'''/* ------------------------------------------------------------------ */
/* Abgeleitete Aussagen                                                */''', r'''const metadataEn = rechnerMetadataEn({
  title: "Solar market data: EEG awards & market value | ÖkoInvest",
  description:
    "Market data for ground-mounted PV: EEG award values since 2017, maximum values, bid volumes, solar market value, capture rate, additions in DACH and lease – with sources.",
