const e = formate("en");
const MONATE_EN = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const terminEn = (iso) => `${Number(iso.slice(8, 10))} ${MONATE_EN[Number(iso.slice(5, 7)) - 1]} ${iso.slice(0, 4)}`;
const ctEn = (v, s = 2) => `${e.fmt(v, s)} ct/kWh`;
const STAND_EN = datumText(MARKTDATEN_STAND_TEXT, "en");
const NAECHSTER_EN = datumText(NAECHSTER_GEBOTSTERMIN, "en");

const ANTWORT_EN = `At the last bidding date on ${terminEn(L.datum)}, the volume-weighted award value for ground-mounted solar installations was ${ctEn(L.mittel)} (previous round: ${ctEn(VORLETZTE.mittel)}). Since ${ERSTER.datum.slice(0, 4)}, results have ranged between ${ctEn(MIN_ZUSCHLAG.mittel)} (${terminEn(MIN_ZUSCHLAG.datum)}) and ${ctEn(MAX_ZUSCHLAG.mittel)} (${terminEn(MAX_ZUSCHLAG.datum)}).`;

const EN = {
  kennzahlen: [
    { wert: e.fmt(L.mittel, 2), text: `Ø solar award, ${terminEn(L.datum)}` },
    { wert: e.fmt(L.gebote / L.volumen, 1), einheit: "×", text: `oversubscribed in ${MONATE_EN[Number(L.datum.slice(5, 7)) - 1]} ${L.datum.slice(0, 4)}` },
    { wert: e.fmt(LETZTER_MARKTWERT.capture * 100), text: `Solar capture rate ${LETZTER_MARKTWERT.jahr}` },
    { wert: e.fmt(NEG_2025.stunden), text: `Hours with negative prices ${NEG_2025.jahr}` },
  ],
  deutschland: "Germany",
  phasen: [
    {
      titel: "2017–2021: Falling costs and stable competition",
      text: `From ${ctEn(ERSTER.mittel)} in February 2017, awards fell to ${ctEn(4.33)} within a year. After that they settled at around 5 ct – with outliers in the special tenders of 2019 – at initially small tender volumes of 100 to 600 MW per bidding date.`,
    },
    {
      titel: "2022–2023: Interest rate turnaround, supply chains, higher maximum value",
      text: "In 2022, some rounds were undersubscribed and awards rose up to the maximum value. The Bundesnetzagentur raised the maximum value for 2023 to 7.37 ct – in March 2023 the average reached 7.03 ct, the highest level since 2017.",
    },
    {
      titel: "Since 2024: Large volumes, strong competition",
      text: `With tender volumes of over 2 GW per bidding date and clear oversubscription, results are again between ${e.fmt(SEIT_2024.min, 2)} and ${e.fmt(SEIT_2024.max, 2)} ct. In 2025, around ${e.fmt(JAHR_2025.zuschlag / 1000, 1)} GW were awarded in three rounds, at an average of ${ctEn(JAHR_2025.mittel)}.`,
    },
  ],
  faq: [
    {
      q: "What is the current award value for ground-mounted solar installations?",
      a: `At the bidding date on ${terminEn(L.datum)}, the volume-weighted average award value was ${ctEn(L.mittel)}; bids between ${ctEn(L.min)} and ${ctEn(L.max)} were awarded. The maximum value was ${ctEn(L.hoechst)}. The next regular bidding date is ${NAECHSTER_EN}.`,
    },
    {
      q: "What does “volume-weighted award value” mean?",
      a: "Each successful bidder receives its own bid value (pay-as-bid). The volume-weighted average weights these values by the respective capacity – so large parks count more than small ones. It is the usual metric for comparing bidding dates.",
    },
    {
      q: "What is the difference between the award value and the solar market value?",
      a: "The award value is the anzulegender Wert (reference value) that a park receives as the floor of its revenue for 20 years – the difference to the market value is paid from the EEG account as a market premium. The solar market value is what solar power actually earns on average on the exchange. If the market value is above the award value, the premium does not apply.",
    },
    {
      q: "What is the capture rate and why is it falling?",
      a: `The capture rate expresses the annual solar market value as a ratio of the average exchange price. In ${LETZTER_MARKTWERT.jahr} it was around ${e.pct(LETZTER_MARKTWERT.capture * 100)}, in ${MW_2020.jahr} still ${e.pct(MW_2020.capture * 100)}. Because more and more solar plants feed in simultaneously at midday, the price falls exactly when solar parks are producing (cannibalisation).`,
