  // AT/CH den LandHinweis (keine geprüften Pachtwerte für AT/CH).
  const land = await seitenLand(params);
  const de = !land || land === "DE";
  const markiert = land !== "DE";
  const kennzahlen = markiert ? KENNZAHLEN.map((k) => ({ ...k, text: `${k.text} · Deutschland` })) : KENNZAHLEN;''', r'''export default async function MarktdatenPage({ params }) {
