// src/components/Fakten/FristenListe.js
//
// Befristete Termine eines Landes aus dem Faktenregister (Welle 2, Paket FRI).
// Zeigt je Termin Zeitraum bzw. Stichtag, Stand (Prüfstatus), Quelle mit Abrufdatum und Ablauf.
//  - Abgelaufene Einträge (gueltigBis vor heute) erscheinen NICHT.
//  - Keine Countdowns, keine Dringlichkeits-Hinweise: nur das Datum.
//  - Land als Parameter (DE | AT | CH); DACH-Termine gelten für alle drei.
// Bewusst ohne JSX (createElement) und ohne Hooks: als Server-Komponente nutzbar und direkt mit
// node --test prüfbar (wie JsonLd.js). Deshalb eigene kleine Stand-/Quellen-Bausteine statt
// StandHinweis/Quellenzeile (JSX); Optik und Texte entsprechen diesen.
//
//   <FristenListe land="AT" />
//   <FristenListe land="DE" heute="2026-10-20" />      Stichtag (Tests, Vorschau)
//   fristenFuer("CH", { heute, liste })                 reine Auswahl (Tests, Berichte)

import { createElement as h } from "react";
import { CalendarDays, CircleCheck, Clock, ExternalLink, PencilRuler, TriangleAlert } from "lucide-react";
import { fakten as faktenAusRegister, anzeigeStatus, istAbgelaufen, datumDe, datumLang, HINWEIS_ABGELAUFEN } from "@/lib/fakten";
import { cn } from "@/components/ui/cn";

export const LAND_NAME = { DE: "Deutschland", AT: "Österreich", CH: "Schweiz", DACH: "Deutschland, Österreich, Schweiz" };

const passtLand = (f, land) => f.land === land || f.land === "DACH";

/**
 * Noch gültige Termine eines Landes, nach Datum sortiert (ohne Entwürfe, ohne Abgelaufene).
 * @param {"DE"|"AT"|"CH"} land
 * @param {{ heute?: Date|string, liste?: object[] }} [optionen] liste: eigene Fakten (Tests)
 */
export function fristenFuer(land, { heute = new Date(), liste } = {}) {
  const quelle = liste || faktenAusRegister({ land, praefix: "termin." });
  return quelle
    .filter((f) => f?.id?.startsWith("termin.") && passtLand(f, land) && f.status !== "entwurf" && !istAbgelaufen(f, heute) && f.wert && typeof f.wert === "object")
    .sort((a, b) => String(a.wert.beginn || a.wert.ende).localeCompare(String(b.wert.beginn || b.wert.ende)));
}

/** Datumstext eines Termins: „8. bis 22. Oktober 2026“, „1. Dezember 2026“, „erwartet bis 31. Dezember 2026“ */
export function terminText(w) {
  if (!w) return "";
  if (w.art === "erwartet") return `erwartet bis ${datumLang(w.ende)}`;
  if (w.art === "zeitraum" && w.beginn) {
    const [jb, mb] = w.beginn.split("-");
    const [je, me] = w.ende.split("-");
    if (jb === je && mb === me) return `${Number(w.beginn.slice(8, 10))}. bis ${datumLang(w.ende)}`;
    if (jb === je) return `${datumLang(w.beginn).replace(` ${jb}`, "")} bis ${datumLang(w.ende)}`;
    return `${datumLang(w.beginn)} bis ${datumLang(w.ende)}`;
  }
  return datumLang(w.ende);
}

/** Stand-Text wie StandHinweis (Masterplan H7): nie „aktuell“ für abgelaufene Werte */
export function standZeile(f, heute = new Date()) {
  const status = anzeigeStatus(f, heute);
  if (status === "abgelaufen") return { status, ton: "warn", text: f.gueltigBis ? `${HINWEIS_ABGELAUFEN} (gültig bis ${datumDe(f.gueltigBis)})` : HINWEIS_ABGELAUFEN };
  const stand = f.abruf ? `Stand ${datumDe(f.abruf)}` : "Stand offen";
  if (status === "geprueft") return { status, ton: "ok", text: `${stand} · am Original geprüft` };
  if (status === "entwurf") return { status, ton: "neutral", text: `${stand} · Entwurf, nicht freigegeben` };
  if (f.klasse === "C" || f.quelle?.art === "eigen") return { status, ton: "neutral", text: `${stand} · eigene Einschätzung` };
  return { status, ton: "neutral", text: `${stand} · Prüfung ausstehend` };
}

const TON = {
  ok: "bg-ov-50 text-ov-800 ring-ov-200",
  warn: "bg-sun-50 text-sun-700 ring-sun-200",
  neutral: "bg-ink-100 text-ink-700 ring-ink-200",
};
const ICON = { geprueft: CircleCheck, abgelaufen: TriangleAlert, zu_pruefen: Clock, entwurf: PencilRuler };

/** Stand-Etikett (Status nie nur über Farbe: Text ist immer dabei) */
export function StandEtikett({ fakt, heute, className }) {
  const { status, ton, text } = standZeile(fakt, heute || new Date());
  return h(
    "span",
    {
      role: status === "abgelaufen" ? "status" : undefined,
      "data-fakt-status": status,
      className: cn("inline-flex max-w-full items-center gap-1.5 rounded-2xl px-2.5 py-1 text-left text-[12px] font-semibold ring-1 ring-inset", TON[ton], className),
    },
    h(ICON[status] || Clock, { "aria-hidden": "true", className: "h-3.5 w-3.5 shrink-0" }),
    h("span", { className: "min-w-0" }, text)
  );
}

/** „Quelle: <Titel> · abgerufen TT.MM.JJJJ“ (wie Quellenzeile) */
export function QuelleZeile({ fakt, className }) {
  const q = fakt?.quelle;
  if (!q) return null;
  const eigen = q.art === "eigen";
  return h(
    "p",
    { className: cn("text-[12.5px] leading-relaxed text-ink-500", className), "data-fakt-quelle": fakt.id },
    h("span", { className: "font-semibold" }, eigen ? "Grundlage: " : "Quelle: "),
    q.url
      ? h(
          "a",
          {
            href: q.url,
            target: "_blank",
            rel: "noopener noreferrer",
            className: "break-words text-ink-700 underline decoration-ink-300 underline-offset-2 transition-colors hover:text-navy-700 hover:decoration-navy-400",
          },
          q.titel,
          h(ExternalLink, { "aria-hidden": "true", className: "ml-0.5 inline h-3 w-3 align-[-1px]" }),
          h("span", { className: "sr-only" }, " (öffnet in neuem Fenster)")
        )
      : h("span", null, q.titel),
    fakt.abruf ? h("span", null, ` · ${eigen ? "Stand" : "abgerufen"} ${datumDe(fakt.abruf)}`) : null
  );
}

/** Text mit **fett** (wie Region/Fett) */
export function mitFett(text) {
  if (typeof text !== "string") return text;
  return text.split(/\*\*(.+?)\*\*/g).map((t, i) => (i % 2 === 1 ? h("strong", { key: i, className: "font-semibold text-ink-900" }, t) : t));
}

export default function FristenListe({ land = "DE", heute, liste, leerText, className }) {
  const jetzt = heute || new Date();
  const eintraege = fristenFuer(land, { heute: jetzt, liste });
  if (!eintraege.length) {
    return h(
      "p",
      { className: cn("rounded-3xl bg-white p-5 text-[14.5px] leading-relaxed text-ink-600 ring-1 ring-ink-200/70", className), "data-fristen-land": land, "data-fristen-leer": "" },
      leerText || `Derzeit sind für ${LAND_NAME[land] || land} keine offenen Termine im Register.`
    );
  }
  return h(
    "ul",
    { className: cn("grid gap-4 md:grid-cols-2", className), "data-fristen-land": land },
    eintraege.map((f) =>
      h(
        "li",
        {
          key: `${f.id}|${f.land}`,
          className: "flex min-w-0 flex-col rounded-3xl bg-white p-5 ring-1 ring-ink-200/70 md:p-6",
          "data-fakt": f.id,
          "data-fakt-land": f.land,
        },
        h(
          "p",
          { className: "inline-flex items-center gap-2 text-[13px] font-semibold text-ov-700" },
          h(CalendarDays, { "aria-hidden": "true", className: "h-4 w-4 shrink-0" }),
          h("span", null, terminText(f.wert))
        ),
        h("h3", { className: "mt-2 font-display text-[17px] font-bold leading-snug text-ink-900" }, f.wert.titel),
        f.wert.text ? h("p", { className: "mt-2.5 text-[14.5px] leading-relaxed text-ink-600" }, mitFett(f.wert.text)) : null,
        h(
          "div",
          { className: "mt-4 flex flex-wrap items-center gap-x-3 gap-y-2" },
          h(StandEtikett, { fakt: f, heute: jetzt }),
          f.gueltigBis ? h("span", { className: "text-[12px] text-ink-500" }, `Eintrag gilt bis ${datumDe(f.gueltigBis)}`) : null
        ),
        h("div", { className: "mt-auto pt-4" }, h(QuelleZeile, { fakt: f, className: "border-t border-ink-200/70 pt-3" }))
      )
    )
  );
}

// src/components/Fakten/BestandteileTabelle.js
//
// Preisbestandteile eines Landes aus dem Faktenregister (Welle 2, Paket FRI): Umlagen und
// Netzentgelte mit Wert, Geltung, Stand (Prüfstatus), Quelle und Ablauf.
//  - Ein offener Wert (wert null) erscheint als „noch nicht veröffentlicht“ – mit dem erwarteten
//    Veröffentlichungstermin aus der Quelle, nie mit einem Schätzwert.
//  - Abgelaufene Einträge (gueltigBis vor heute) erscheinen nicht.
//  - Land als Parameter (DE | AT | CH); CH-Werte in CHF/Rp. über fmtFaktWert.
// Bewusst ohne JSX (createElement) und ohne Hooks – siehe FristenListe.js.
//
//   <BestandteileTabelle land="DE" />
//   bestandteileFuer("AT", { heute, liste })      reine Auswahl (Tests, Berichte)

import { createElement as h } from "react";
import { fakten as faktenAusRegister, istAbgelaufen, datumDe, fmtFaktWert } from "@/lib/fakten";
import { cn } from "@/components/ui/cn";
import { LAND_NAME, QuelleZeile, StandEtikett } from "./FristenListe";

export const PRAEFIXE_BESTANDTEILE = ["umlage.", "netzentgelt."];

/** Anzeigenamen der Bestandteile (unbekannte ids erscheinen mit ihrer id) */
export const BESTANDTEIL_NAME = {
  "umlage.kwkg": "KWKG-Umlage",
  "umlage.offshoreNetz": "Offshore-Netzumlage",
  "umlage.besondereNetznutzung": "Aufschlag für besondere Netznutzung",
  "netzentgelt.de.struktur": "Netzentgelte (Aufbau)",
  "netzentgelt.at.sne2027": "Systemnutzungsentgelte 2027",
  "netzentgelt.ch.elcomTarife2027": "Stromtarife 2027 der Grundversorgung",
};

export const TEXT_OFFEN = "noch nicht veröffentlicht";

/** „Veröffentlichung erwartet bis TT.MM.JJJJ“ aus der Notiz eines offenen Werts (oder null) */
export function erwarteteVeroeffentlichung(f) {
  const m = typeof f?.notiz === "string" ? f.notiz.match(/Veröffentlichung erwartet bis (\d{2}\.\d{2}\.\d{4})/) : null;
  return m ? m[1] : null;
}

/** Notiz ohne den (schon in der Wert-Spalte gezeigten) Satz „Veröffentlichung erwartet bis …“ */
const notizOhneTermin = (f) => (typeof f?.notiz === "string" ? f.notiz.replace(/Veröffentlichung erwartet bis \d{2}\.\d{2}\.\d{4}\.?\s*/, "").trim() : "");

/** Anzeigetext des Werts: offener Wert → „noch nicht veröffentlicht“ */
export function bestandteilWert(f, land = f?.land) {
  if (!f || f.wert === null || f.wert === undefined) return TEXT_OFFEN;
  return fmtFaktWert(f, land);
}

/**
 * Noch gültige Umlagen und Netzentgelte eines Landes (ohne Entwürfe, ohne Abgelaufene),
 * Umlagen vor Netzentgelten, sonst in Registerreihenfolge.
 */
export function bestandteileFuer(land, { heute = new Date(), liste } = {}) {
  const quelle = liste || PRAEFIXE_BESTANDTEILE.flatMap((praefix) => faktenAusRegister({ land, praefix }));
  const rang = (f) => PRAEFIXE_BESTANDTEILE.findIndex((p) => f.id.startsWith(p));
  return quelle
    .filter((f) => typeof f?.id === "string" && rang(f) >= 0 && (f.land === land || f.land === "DACH") && f.status !== "entwurf" && !istAbgelaufen(f, heute))
    .map((f, i) => ({ f, i }))
    .sort((a, b) => rang(a.f) - rang(b.f) || a.i - b.i)
    .map(({ f }) => f);
}

const geltung = (f) => {
  if (f.gueltigAb && f.gueltigBis) return `${datumDe(f.gueltigAb)} bis ${datumDe(f.gueltigBis)}`;
  if (f.gueltigAb) return `ab ${datumDe(f.gueltigAb)}`;
  if (f.gueltigBis) return `bis ${datumDe(f.gueltigBis)}`;
  return "laufend, bis zur nächsten Änderung";
};

const ZELLE = "align-top px-4 py-4 max-md:block max-md:px-0 max-md:py-1.5 max-md:before:mb-0.5 max-md:before:block max-md:before:text-[11.5px] max-md:before:font-semibold max-md:before:uppercase max-md:before:tracking-[0.08em] max-md:before:text-ink-500 max-md:before:content-[attr(data-label)]";

export default function BestandteileTabelle({ land = "DE", heute, liste, beschriftung, className }) {
  const jetzt = heute || new Date();
  const zeilen = bestandteileFuer(land, { heute: jetzt, liste });
  if (!zeilen.length) {
    return h(
      "p",
      { className: cn("rounded-3xl bg-white p-5 text-[14.5px] leading-relaxed text-ink-600 ring-1 ring-ink-200/70", className), "data-bestandteile-land": land, "data-bestandteile-leer": "" },
      `Für ${LAND_NAME[land] || land} sind derzeit keine Preisbestandteile im Register.`
    );
  }
  const kopf = ["Bestandteil", "Wert", "Gilt", "Stand und Quelle"];
  return h(
    "div",
    { className: cn("overflow-hidden rounded-3xl bg-white ring-1 ring-ink-200/70", className), "data-bestandteile-land": land },
    h(
      "table",
      { className: "w-full border-collapse text-left text-[14.5px] max-md:block" },
      h("caption", { className: "sr-only" }, beschriftung || `Preisbestandteile ${LAND_NAME[land] || land}`),
      h(
        "thead",
        { className: "bg-sand-50 max-md:sr-only" },
        h(
          "tr",
          null,
          kopf.map((k) => h("th", { key: k, scope: "col", className: "px-4 py-3 text-[12px] font-semibold uppercase tracking-[0.08em] text-ink-500" }, k))
        )
      ),
      h(
        "tbody",
        { className: "max-md:block" },
        zeilen.map((f) => {
          const offen = f.wert === null || f.wert === undefined;
          const erwartet = offen ? erwarteteVeroeffentlichung(f) : null;
          return h(
            "tr",
            {
              key: `${f.id}|${f.land}|${f.gueltigAb || ""}`,
              className: "border-t border-ink-200/70 max-md:block max-md:px-5 max-md:py-4 first:max-md:border-t-0",
              "data-fakt": f.id,
              "data-fakt-land": f.land,
              "data-fakt-offen": offen ? "" : undefined,
            },
            h("th", { scope: "row", "data-label": kopf[0], className: cn(ZELLE, "font-display text-[15.5px] font-bold text-ink-900 md:w-[22%]") }, BESTANDTEIL_NAME[f.id] || f.id),
            h(
              "td",
              { "data-label": kopf[1], className: cn(ZELLE, "md:w-[30%]") },
              h("span", { className: offen ? "font-semibold text-ink-600" : "font-semibold text-ink-900" }, bestandteilWert(f, land)),
              erwartet ? h("span", { className: "mt-1 block text-[13px] text-ink-500" }, `Veröffentlichung erwartet bis ${erwartet}`) : null
            ),
            h("td", { "data-label": kopf[2], className: cn(ZELLE, "text-ink-700 md:w-[16%]") }, geltung(f)),
            h(
              "td",
              { "data-label": kopf[3], className: ZELLE },
              h(StandEtikett, { fakt: f, heute: jetzt }),
              h(QuelleZeile, { fakt: f, className: "mt-2" }),
              notizOhneTermin(f) ? h("p", { className: "mt-1.5 text-[12.5px] leading-relaxed text-ink-500" }, notizOhneTermin(f)) : null
            )
          );
        })
      )
    )
  );
}
