(r'''<p className="mt-3 text-[12px] text-white/60">Quelle: Bundesnetzagentur, mengengewichteter Durchschnitt je Gebotstermin</p>''', r'''<p className="mt-3 text-[12px] text-white/60">{t.quelle}</p>'''),
]

