  const q = fakt?.quelle;
  if (!q) return null;
  const eigen = q.art === "eigen";
  const en = sprache === "en";'''),
(r'''h("span", { className: "font-semibold" }, eigen ? "Grundlage: " : "Quelle: "),''', r'''h("span", { className: "font-semibold" }, en ? (eigen ? "Basis: " : "Source: ") : eigen ? "Grundlage: " : "Quelle: "),'''),
(r'''          q.titel,
          h(ExternalLink, { "aria-hidden": "true", className: "ml-0.5 inline h-3 w-3 align-[-1px]" }),
          h("span", { className: "sr-only" }, " (öffnet in neuem Fenster)")
        )
      : h("span", null, q.titel),
    fakt.abruf ? h("span", null, ` · ${eigen ? "Stand" : "abgerufen"} ${datumDe(fakt.abruf)}`) : null''', r'''          en ? quelleTitelEn(q) : q.titel,
          h(ExternalLink, { "aria-hidden": "true", className: "ml-0.5 inline h-3 w-3 align-[-1px]" }),
          h("span", { className: "sr-only" }, en ? " (opens in a new window)" : " (öffnet in neuem Fenster)")
