        f.wert.text ? h("p", { className: "mt-2.5 text-[14.5px] leading-relaxed text-ink-600" }, mitFett(f.wert.text)) : null,''', r'''          h("span", null, en ? terminTextEn(f.wert) : terminText(f.wert))
        ),
