const norm = (s) =>
  String(s || "")
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss");

/**
 * Zentrale FAQ mit Suchfeld und Gruppenfilter. Das FAQPage-Schema liefert
