"use client";

import { useDeferredValue, useEffect, useMemo, useState } from "react";
import Link from "@/components/Land/Link";
import { ArrowUpRight, Search, X } from "lucide-react";
import { pfad } from "@/lib/land";

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

/** Kleinschreibung, Umlaute/ß vereinheitlicht, Sonderzeichen entfernt – für tolerante Suche. */
const norm = (s) =>
  s
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss")
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .replace(/[^a-z0-9% ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

/**
 * Fachlexikon mit Live-Suche, Themenfilter und klebender A–Z-Leiste.
 * Alle Begriffe werden serverseitig vollständig gerendert (SEO, Anker-IDs);
 * Filter blenden nur aus.
 *
 * props:
 *  gruppen    [[buchstabe, [begriff, ...]], ...]
 *  kategorien [{ id, label, anzahl? }]
 *  namen      { id: begriff } – für Beschriftung verwandter Begriffe
 */
export default function LexikonExplorer({ gruppen, kategorien, namen }) {
  const [suche, setSuche] = useState("");
  const [kategorie, setKategorie] = useState("alle");
  const q = useDeferredValue(suche);

  // Suche aus dem Hero übernehmen (Ereignis mit JS, ?q=… ohne JS)
  useEffect(() => {
    const start = new URLSearchParams(window.location.search).get("q");
    if (start) setSuche(start);
    const onSuche = (e) => {
      setSuche(e.detail || "");
      setKategorie("alle");
    };
    window.addEventListener("lexikon:suche", onSuche);
    return () => window.removeEventListener("lexikon:suche", onSuche);
  }, []);

  const index = useMemo(
    () =>
      new Map(
        gruppen.flatMap(([, liste]) =>
          liste.map((b) => [
            b.id,
            { titel: norm(`${b.begriff} ${(b.synonyme || []).join(" ")}`), voll: norm(`${b.kurz} ${b.text}`) },
          ])
        )
      ),
    [gruppen]
  );

  const gefiltert = useMemo(() => {
    const nq = norm(q);
    const woerter = nq ? nq.split(" ") : [];
    return gruppen
      .map(([l, liste]) => {
        const treffer = liste
          .filter((b) => kategorie === "alle" || b.kategorie === kategorie)
          .map((b) => {
            if (!woerter.length) return { b, score: 0 };
            const i = index.get(b.id);
            let score = 0;
            for (const w of woerter) {
              if (i.titel.startsWith(w)) score += 5;
              else if (i.titel.includes(w)) score += 3;
              else if (i.voll.includes(w)) score += 1;
              else return null;
            }
            return { b, score };
          })
          .filter(Boolean)
          .sort((x, y) => y.score - x.score)
          .map((x) => x.b);
        return [l, treffer];
      })
      .filter(([, t]) => t.length > 0);
  }, [gruppen, index, q, kategorie]);

  const anzahl = gefiltert.reduce((a, [, t]) => a + t.length, 0);
  const vorhanden = new Set(gefiltert.map(([l]) => l));
  const aktivFilter = q.trim() !== "" || kategorie !== "alle";

  const springe = (l) => {
    const el = document.getElementById(`buchstabe-${l}`);
    if (!el) return;
    el.scrollIntoView({ behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" });
  };

  return (
    <div>
      {/* ---------- Themen ---------- */}
      <div className="flex flex-col gap-1 md:flex-row md:items-end md:justify-between md:gap-10">
        <h2 className="ov-h3 text-ink-900 md:text-[28px]">Alle Begriffe</h2>
        <p className="text-[14.5px] text-ink-500">Nach Themenfeld filtern, suchen oder über das Alphabet springen.</p>
      </div>
      <div className="ov-no-scrollbar -mx-5 mt-5 flex gap-2 overflow-x-auto px-5 pb-1 md:-mx-8 md:px-8 lg:mx-0 lg:flex-wrap lg:px-0" role="group" aria-label="Nach Thema filtern">
        {[{ id: "alle", label: "Alle Themen", anzahl: gruppen.reduce((s, [, l]) => s + l.length, 0) }, ...kategorien].map((k) => {
          const aktiv = kategorie === k.id;
          return (
            <button
              key={k.id}
              type="button"
              aria-pressed={aktiv}
              onClick={() => setKategorie(k.id)}
              className={`inline-flex h-11 shrink-0 items-center gap-2 whitespace-nowrap rounded-full px-4 text-[14px] font-semibold transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2 ${
                aktiv ? "bg-ink-900 text-white shadow-md" : "bg-white text-ink-700 ring-1 ring-ink-200 hover:text-ink-900 hover:ring-ink-300"
              }`}
            >
              {k.label}
              {typeof k.anzahl === "number" && (
                <span className={`ov-num rounded-full px-1.5 text-[12px] ${aktiv ? "bg-white/15 text-white" : "bg-ink-100 text-ink-600"}`}>{k.anzahl}</span>
              )}
            </button>
          );
        })}
      </div>

      {/* ---------- Klebende Leiste: Suche + A–Z ---------- */}
      <div className="sticky top-[68px] z-30 -mx-5 mt-6 border-y border-ink-200/80 bg-sand-50/90 px-5 py-3 backdrop-blur-xl md:-mx-8 md:px-8 lg:mx-0 lg:rounded-2xl lg:border lg:bg-white/90 lg:px-3 lg:py-3 lg:shadow-[0_10px_30px_-18px_rgba(21,26,36,0.25)]">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:gap-4">
          <div className="relative lg:w-[300px] lg:shrink-0">
            <Search aria-hidden="true" className="pointer-events-none absolute left-4 top-1/2 h-[18px] w-[18px] -translate-y-1/2 text-ink-400" />
            <label htmlFor="lexikon-suche" className="sr-only">
              Begriff suchen
            </label>
            <input
              id="lexikon-suche"
              type="search"
              value={suche}
              onChange={(e) => setSuche(e.target.value)}
              placeholder="Begriff suchen, z. B. Pacht"
              autoComplete="off"
              className="h-12 w-full rounded-full bg-white pl-11 pr-11 text-[15px] text-ink-900 ring-1 ring-ink-200 placeholder:text-ink-500 focus:outline-none focus:ring-2 focus:ring-ov-500 lg:bg-ink-50 [&::-webkit-search-cancel-button]:hidden"
            />
            {suche && (
              <button
                type="button"
                onClick={() => setSuche("")}
                aria-label="Suche leeren"
                className="absolute right-1.5 top-1/2 flex h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full text-ink-500 hover:bg-ink-100 hover:text-ink-900"
              >
                <X aria-hidden="true" className="h-4 w-4" />
              </button>
            )}
          </div>

          <nav aria-label="Alphabetische Sprungleiste" className="ov-no-scrollbar -mx-5 overflow-x-auto px-5 md:-mx-8 md:px-8 lg:mx-0 lg:flex-1 lg:px-0">
            <ul className="flex min-w-max gap-0.5 lg:min-w-0 lg:justify-between">
              {ALPHABET.map((l) => {
                const ok = vorhanden.has(l);
                return (
                  <li key={l}>
                    <button
                      type="button"
                      disabled={!ok}
                      onClick={() => springe(l)}
                      aria-label={ok ? `Zu Buchstabe ${l}` : `Buchstabe ${l} – keine Begriffe`}
                      className="flex h-10 w-9 items-center justify-center rounded-lg font-display text-[14.5px] font-bold text-ink-800 transition-colors hover:bg-ov-500 hover:text-white disabled:cursor-default disabled:text-ink-300 disabled:hover:bg-transparent lg:h-9 lg:w-8"
                    >
                      {l}
                    </button>
                  </li>
                );
              })}
            </ul>
          </nav>
        </div>
      </div>

      <p className="mt-6 text-[14px] text-ink-500" aria-live="polite">
        {aktivFilter ? (
          <>
            <span className="ov-num font-semibold text-ink-900">{anzahl}</span> {anzahl === 1 ? "Begriff" : "Begriffe"} gefunden
            <button
              type="button"
              onClick={() => {
                setSuche("");
                setKategorie("alle");
              }}
              className="ml-3 font-semibold text-ov-700 underline decoration-ov-300 underline-offset-2 hover:decoration-current"
            >
              Filter zurücksetzen
            </button>
          </>
        ) : (
          <>
            <span className="ov-num font-semibold text-ink-900">{anzahl}</span> Fachbegriffe von A bis Z
          </>
        )}
      </p>

      {/* ---------- Begriffe ---------- */}
      {gefiltert.length === 0 ? (
        <div className="mt-8 rounded-3xl bg-white p-10 text-center ring-1 ring-ink-200/70">
          <p className="font-display text-[20px] font-extrabold text-ink-900">Kein Begriff gefunden</p>
          <p className="mx-auto mt-2 max-w-md text-[15px] leading-relaxed text-ink-600">
            Versuchen Sie ein anderes Stichwort – oder fragen Sie uns direkt. Wir ergänzen das Lexikon laufend.
          </p>
          <div className="mt-6 flex flex-wrap justify-center gap-3">
            <Link href={pfad("/faq")} className="inline-flex h-11 items-center rounded-full bg-ink-900 px-5 text-[14px] font-semibold text-white hover:bg-ink-800">
              Häufige Fragen
            </Link>
            <Link href="/kontakt" className="inline-flex h-11 items-center rounded-full px-5 text-[14px] font-semibold text-ink-800 ring-1 ring-ink-200 hover:bg-ink-50">
              Frage stellen
            </Link>
          </div>
        </div>
      ) : (
        <div className="mt-4">
          {gefiltert.map(([l, liste]) => (
            <section key={l} id={`buchstabe-${l}`} aria-labelledby={`buchstabe-${l}-titel`} className="scroll-mt-[220px] border-t border-ink-200/80 pt-8 first:border-t-0 lg:scroll-mt-[160px] lg:pt-10">
              <div className="grid gap-5 pb-10 lg:grid-cols-[88px_minmax(0,1fr)] lg:gap-10">
                <div className="flex items-center gap-4 lg:sticky lg:top-[160px] lg:block lg:self-start">
                  <h2 id={`buchstabe-${l}-titel`} className="flex h-14 w-14 items-center justify-center rounded-2xl bg-white font-display text-[30px] font-extrabold leading-none tracking-tight text-ov-600 shadow-e1 ring-1 ring-ink-200/70 lg:h-[88px] lg:w-[88px] lg:text-[48px]">
                    {l}
                  </h2>
                  <p className="ov-num text-[13px] font-medium text-ink-500 lg:mt-3 lg:text-center">
                    {liste.length} {liste.length === 1 ? "Begriff" : "Begriffe"}
                  </p>
                </div>
                <dl className="grid gap-4 md:grid-cols-2">
                  {liste.map((b) => (
                    <Eintrag key={b.id} b={b} namen={namen} kategorien={kategorien} />
                  ))}
                </dl>
              </div>
            </section>
          ))}
        </div>
      )}
    </div>
  );
}

function Eintrag({ b, namen, kategorien }) {
  const kat = kategorien.find((k) => k.id === b.kategorie)?.label;
  return (
    <div
      id={b.id}
      className="group relative flex scroll-mt-[220px] flex-col rounded-3xl bg-white p-6 shadow-e1 ring-1 ring-ink-200/70 transition-shadow duration-300 target:ring-2 target:ring-ov-500 target:shadow-[0_0_0_6px_rgba(102,153,51,0.15)] hover:shadow-e3 hover:ring-ov-200 lg:scroll-mt-[170px] md:p-7"
    >
      {/* dl-Gruppe enthält nur dt/dd – Themen-Chip steckt mit im dt */}
      <dt className="flex flex-col-reverse items-start gap-2 sm:flex-row sm:justify-between sm:gap-3">
        <a href={`#${b.id}`} className="font-display text-[19px] font-extrabold leading-snug tracking-tight text-ink-900 hover:text-ov-700">
          {b.begriff}
        </a>
        {kat && (
          <span className="mt-0.5 shrink-0 rounded-full bg-sand-100 px-2.5 py-1 text-[11px] font-semibold uppercase tracking-wider text-ink-600">
            <span className="sr-only">Thema: </span>
            {kat}
          </span>
        )}
      </dt>
      <dd className="mt-3 flex flex-1 flex-col">
        <p className="border-l-2 border-ov-400 pl-3.5 text-[15.5px] font-medium leading-relaxed text-ink-800">{b.kurz}</p>
        <p className="mt-3 text-[15px] leading-relaxed text-ink-600">{b.text}</p>
        {b.synonyme?.length > 0 && (
          <p className="mt-3 text-[13px] leading-relaxed text-ink-500">
            <span className="font-semibold text-ink-600">Auch:</span> {b.synonyme.join(", ")}
          </p>
        )}
        {(b.verwandt?.length > 0 || b.link) && (
          <div className="mt-auto flex flex-wrap items-center gap-2 pt-5">
            {b.verwandt?.map((v) => (
              <a key={v} href={`#${v}`} className="inline-flex min-h-[32px] items-center rounded-full bg-ink-50 px-3 text-[12.5px] font-medium text-ink-600 ring-1 ring-ink-100 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-200">
                {namen[v] || v}
              </a>
            ))}
            {b.link && (
              <Link href={b.link.href} className="ml-auto inline-flex min-h-[32px] items-center gap-1 text-[13.5px] font-semibold text-ov-700 hover:text-ov-800">
                {b.link.label}
                <ArrowUpRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:-translate-y-0.5 group-hover:translate-x-0.5" />
              </Link>
            )}
          </div>
        )}
      </dd>
    </div>
  );
}
// Hero des Lexikons: Suche als Hauptaktion, rechts das Alphabet als
// Dichtekarte (echte Begriffszahl je Buchstabe) und der Begriff im Fokus.
import { ArrowDown } from "lucide-react";
import HeroTitel from "@/components/Unternehmen/HeroTitel";

import Breadcrumbs from "@/components/ui/Breadcrumbs";
import HeroSuche from "./HeroSuche";

const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

/**
 * props:
 *  anzahl     Gesamtzahl Begriffe
 *  proBuchstabe { A: 12, … }
 *  kennzahlen [{ wert, label }]
 *  fokus      { id, begriff, kurz } | null
 *  beliebt    [{ id, begriff }]
 *  stand      Text, z. B. „September 2026“
 */
export default function LexikonHero({ anzahl, proBuchstabe = {}, kennzahlen = [], fokus, beliebt = [], stand }) {
  const max = Math.max(1, ...Object.values(proBuchstabe));

  return (
    <section aria-labelledby="lexikon-titel" className="ov-verlauf-nacht ov-noise relative isolate overflow-hidden text-white">
      <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10 opacity-50" />
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-px bg-gradient-to-r from-transparent via-ov-300/40 to-transparent" />
      <div aria-hidden="true" className="pointer-events-none absolute -left-40 -top-40 -z-10 h-[520px] w-[520px] rounded-full bg-ov-500/20 blur-[120px]" />
      {/* Großes Monogramm als Bühnenhintergrund */}
      <p aria-hidden="true" className="pointer-events-none absolute -bottom-16 right-[-2rem] -z-10 select-none font-display text-[15rem] font-extrabold leading-none tracking-tighter text-white/[0.03] md:text-[22rem]">
        A–Z
      </p>

      <div className="ov-container pb-20 pt-6 sm:pt-8 md:pb-28 md:pt-10">
        <Breadcrumbs items={[{ name: "Ratgeber", href: "/ratgeber" }, { name: "Lexikon" }]} dark className="ov-hero-in mb-8 md:mb-12" />

        <div className="grid items-center gap-y-14 lg:grid-cols-[minmax(0,1fr)_minmax(0,0.95fr)] lg:gap-x-12 xl:gap-x-20">
          {/* ---------- Text ---------- */}
          <div className="max-w-[37rem]">
            <p
              className="ov-hero-in inline-flex max-w-full items-center gap-2.5 rounded-full bg-white/[0.06] py-1 pl-1 pr-3.5 text-[13px] text-white/85 ring-1 ring-inset ring-white/15"
              style={{ "--ov-delay": "40ms" }}
            >
              <span className="shrink-0 rounded-full bg-ov-300 px-2 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em] text-navy-950">Wissen</span>
              <span className="min-w-0 truncate">Stand {stand} · laufend gepflegt</span>
            </p>

            <h1 id="lexikon-titel" className="ov-h1 mt-6 text-balance md:mt-8">
              <HeroTitel><>Lexikon: <span className="ov-text-gradient-light">Fachbegriffe</span> von A bis Z</></HeroTitel>
            </h1>

            <p className="ov-lead ov-hero-in mt-5 text-pretty text-white/75 md:mt-6" style={{ "--ov-delay": "180ms" }}>
              Von Aufstellungsbeschluss bis Zuschlagswert: die Begriffe aus Pachtvertrag, Bebauungsplan, Netzanschluss, Ausschreibung und Projektkauf –{" "}
              <span className="font-medium text-white">jeweils mit einer Definition in einem Satz</span>, einer Erklärung für Deutschland, Österreich und
              die Schweiz und dem Weg zum passenden Rechner.
            </p>

            <div className="ov-hero-in mt-8 md:mt-10" style={{ "--ov-delay": "260ms" }}>
              <HeroSuche />
              {beliebt.length > 0 && (
                <div className="mt-4 flex flex-wrap items-center gap-2 text-[13.5px]">
                  <span className="mr-1 text-white/60">Zum Einstieg:</span>
                  {beliebt.map((b) => (
                    <a
                      key={b.id}
                      href={`#${b.id}`}
                      className="inline-flex min-h-[34px] items-center rounded-full bg-white/[0.06] px-3.5 font-medium text-white/85 ring-1 ring-inset ring-white/15 transition-colors hover:bg-white/[0.12] hover:text-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-300"
                    >
                      {b.begriff}
                    </a>
                  ))}
                </div>
              )}
            </div>

            {kennzahlen.length > 0 && (
              <dl className="ov-hero-in mt-10 grid grid-cols-3 gap-4 border-t border-white/10 pt-7 sm:gap-6" style={{ "--ov-delay": "340ms" }}>
                {kennzahlen.map((k) => (
                  <div key={k.label} className="min-w-0">
                    <dt className="sr-only">{k.label}</dt>
                    <dd className="ov-kpi text-white">{k.wert}</dd>
                    <dd className="mt-1.5 text-[13px] leading-snug text-white/65">{k.label}</dd>
                  </div>
                ))}
              </dl>
            )}
          </div>

          {/* ---------- Bühne: Alphabet-Dichtekarte + Begriff im Fokus ---------- */}
          <div className="ov-hero-in relative mx-auto w-full max-w-[560px] lg:mx-0 lg:max-w-none" style={{ "--ov-delay": "220ms" }}>
