        <p className="mb-6 mt-3 line-clamp-3 text-[15px] leading-relaxed text-ink-600">{a.excerpt}</p>
        <div className="mt-auto flex items-center justify-between gap-4 border-t border-ink-100 pt-4 text-[13px] text-ink-500">
