('''    { wert: "in Prüfung", text: `${landHinweisText(land, "Pacht- und Förderwerte")}.`, href: "/kontakt" },''', '''    { wert: t.inPruefung, text: `${landHinweisText(land, en ? "Lease and support values" : "Pacht- und Förderwerte", sprache)}.`, href: "/kontakt" },'''),
