          </div>
          <p className="max-w-sm text-[15.5px] leading-relaxed text-ink-600">{t.alleText}</p>'''),
('''          kategorien={KATEGORIEN}
          artikel={artikel.map(({ slug, title, excerpt, kategorie, bild, bildAlt, lesezeit, keywords }) => ({ slug, title, excerpt, kategorie, bild, bildAlt, lesezeit, keywords: keywords || [] }))}''', '''          kategorien={KATEGORIEN}
