        title={t.ctaTitel}
        text={t.ctaText}'''),
('''export const generateMetadata = seitenMetadata("/ratgeber", metadata);''', '''export const generateMetadata = seitenMetadata("/ratgeber", metadata, { en: metadataEn });'''),
]

