// Ganzseiten-Aufnahme DE/EN (Banner auf Deutsch oder Englisch) (scrollt durch, damit Reveal-Animationen auslösen)
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
const [basis, out, breitenArg, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const browser = await chromium.launch();
const ctx = await browser.newContext({ reducedMotion: "reduce" });
for (const w of breitenArg.split(",").map(Number)) {
  const page = await ctx.newPage();
  await page.setViewportSize({ width: w, height: w < 700 ? 844 : 900 });
  for (const pfad of pfade) {
    const fehler = [];
    page.on("pageerror", (e) => fehler.push(String(e)));
    try {
      const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 180000 });
      await page.locator("button", { hasText: /^(Nur notwendige|Necessary only)$/ }).first().click({ timeout: 3000 }).catch(() => {});
      await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 500) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 60)); } window.scrollTo(0, 0); });
      await page.waitForTimeout(800);
      const breite = await page.evaluate(() => document.documentElement.scrollWidth);
      const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "") || "start";
      await page.screenshot({ path: `${out}/voll-w${w}-${name}.png`, fullPage: true });
      console.log(`w${w} ${pfad} status=${r?.status()} breite=${breite}${breite > w ? " UEBERLAUF" : ""} fehler=${fehler.length}`);
    } catch (e) {
      console.log(`w${w} ${pfad} FEHLER ${String(e).slice(0, 120)}`);
    }
  }
  await page.close();
}
